/* Deutsch Trainer — drills for the original 55 grammar lessons.
   8 gap drills per lesson of grammar.js, keyed by lesson id (gid).
   lv / sk mirror the lesson they belong to.  */
window.DRILL_CORE=[

/* ---- alphabet ---- */
{gid:'alphabet',lv:1,sk:'Beginner',s:'Das Wort „Fuß“ schreibt man mit ___ .',a:'ß',o:['s','sch','z'],
 ex:'ß (Eszett) stands for a sharp s after a long vowel: Fuß, Straße, groß.',tr:'The word „Fuß“ is written with ß.',say:'Das Wort „Fuß“ schreibt man mit ß.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Die drei deutschen Umlaute sind ä, ö und ___ .',a:'ü',o:['ß','y','e'],
 ex:'There are exactly three Umlaute: ä, ö, ü. ß is not an Umlaut but a sharp s.',tr:'The three German umlauts are ä, ö and ü.',say:'Die drei deutschen Umlaute sind ä, ö und ü.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Das deutsche Alphabet hat ___ Buchstaben plus ä, ö, ü und ß.',a:'26',o:['24','28','30'],
 ex:'German uses the same 26 Latin letters as English and adds four extra signs.',tr:'The German alphabet has 26 letters plus ä, ö, ü and ß.',say:'Das deutsche Alphabet hat 26 Buchstaben plus ä, ö, ü und ß.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Ohne Umlaut-Taste schreibt man „Tür“ als ___ .',a:'Tuer',o:['Tur','Tüer','Tuör'],
 ex:'ü may be replaced by ue → Tuer. Simply dropping the dots (Tur) is wrong.',tr:'Without an umlaut key you write „Tür“ as Tuer.',say:'Ohne Umlaut-Taste schreibt man „Tür“ als Tuer.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Ohne ß-Taste schreibt man „Straße“ als ___ .',a:'Strasse',o:['Strase','Straze','Strasze'],
 ex:'ß may be written ss → Strasse. One s only (Strase) would change the vowel length.',tr:'Without an ß key you write „Straße“ as Strasse.',say:'Ohne ß-Taste schreibt man „Straße“ als Strasse.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Im Wort „Bär“ steht der Umlaut ___ .',a:'ä',o:['ö','ü','ß'],
 ex:'Bär has an a with two dots: ä. The Umlaut changes the vowel sound completely.',tr:'In the word „Bär“ there is the umlaut ä.',say:'Im Wort „Bär“ steht der Umlaut ä.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'___ ist ein Tier.',a:'Der Bär',o:['der Bär','Der bär','der bär'],
 ex:'Two capitals are needed: the sentence start and the noun → Der Bär.',tr:'The bear is an animal.',say:'Der Bär ist ein Tier.'},
{gid:'alphabet',lv:1,sk:'Beginner',s:'Ich wohne in der ___ Nummer 5.',a:'Straße',o:['straße','Straase','Strase'],
 ex:'Capital S because it is a noun, and ß after the long a: Straße.',tr:'I live at number 5 in this street.',say:'Ich wohne in der Straße Nummer 5.'},

/* ---- greetings ---- */
{gid:'greetings',lv:1,sk:'Beginner',s:'Um acht Uhr morgens sagt man: „Guten ___!“',a:'Morgen',o:['Tag','Abend','Nacht'],
 ex:'Until about 11 a.m. the greeting is Guten Morgen.',tr:'At eight in the morning you say „Good morning!“',say:'Guten Morgen!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Um zwanzig Uhr sagt man: „Guten ___!“',a:'Abend',o:['Morgen','Tag','Nacht'],
 ex:'From early evening on: Guten Abend. Gute Nacht is only for going to bed.',tr:'At eight in the evening you say „Good evening!“',say:'Guten Abend!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Formell sagt man beim Abschied: „Auf ___!“',a:'Wiedersehen',o:['Tschüss','Hallo','Danke'],
 ex:'Auf Wiedersehen is the formal goodbye; Tschüss is informal.',tr:'Formally you say „Goodbye!“ when leaving.',say:'Auf Wiedersehen!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Jemand hilft dir. Du sagst: „___!“',a:'Danke',o:['Bitte','Hallo','Tschüss'],
 ex:'Danke thanks somebody; Bitte is the answer to it.',tr:'Somebody helps you. You say „Thank you!“',say:'Danke!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'„Danke schön!“ — „___!“',a:'Bitte',o:['Danke','Hallo','Entschuldigung'],
 ex:'Bitte also means „you’re welcome“ — the standard reply to Danke.',tr:'„Thank you very much!“ — „You’re welcome!“',say:'Danke schön! Bitte!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Du stößt jemanden an und sagst: „___!“',a:'Entschuldigung',o:['Bitte','Danke','Tschüss'],
 ex:'Entschuldigung covers both „sorry“ and „excuse me“.',tr:'You bump into somebody and say „Sorry!“',say:'Entschuldigung!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Zu einer Freundin sagt man zum Abschied: „___!“',a:'Tschüss',o:['Auf Wiedersehen','Guten Tag','Entschuldigung'],
 ex:'Tschüss is the informal goodbye you use with du-people.',tr:'To a friend you say „Bye!“ when leaving.',say:'Tschüss!'},
{gid:'greetings',lv:1,sk:'Beginner',s:'Wie geht es ___ ? (formell)',a:'Ihnen',o:['dir','ihnen','du'],
 ex:'The formal Sie has the dative Ihnen, always with a capital I; dir belongs to du.',tr:'How are you? (formal)',say:'Wie geht es Ihnen?'},

/* ---- numbers ---- */
{gid:'numbers',lv:1,sk:'Numbers',s:'7 + 6 = ___',a:'dreizehn',o:['dreiundzehn','dreizig','zehndrei'],
 ex:'13–19 are unit + -zehn, so drei + zehn = dreizehn.',tr:'7 + 6 = 13.',say:'Sieben plus sechs ist dreizehn.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'10 + 6 = ___',a:'sechzehn',o:['sechszehn','sechsundzehn','sechzig'],
 ex:'16 drops the s of sechs: sechzehn, never „sechszehn“.',tr:'10 + 6 = 16.',say:'Zehn plus sechs ist sechzehn.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'10 + 7 = ___',a:'siebzehn',o:['siebenzehn','siebzig','siebenundzehn'],
 ex:'17 drops the -en of sieben: siebzehn, never „siebenzehn“.',tr:'10 + 7 = 17.',say:'Zehn plus sieben ist siebzehn.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'Nach elf kommt ___ .',a:'zwölf',o:['zweizehn','zwolf','elfzehn'],
 ex:'11 and 12 have their own words: elf, zwölf — the -zehn pattern only starts at 13.',tr:'After eleven comes twelve.',say:'Nach elf kommt zwölf.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'2 × 10 = ___',a:'zwanzig',o:['zweizig','zweizehn','zwanzehn'],
 ex:'20 is zwanzig; -zig marks the tens, -zehn the teens.',tr:'2 × 10 = 20.',say:'Zwei mal zehn ist zwanzig.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'Die Zahl 0 heißt auf Deutsch ___ .',a:'null',o:['nul','nulle','zero'],
 ex:'0 = null, with a double l.',tr:'The number 0 is called null in German.',say:'Die Zahl 0 heißt auf Deutsch null.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'Ich habe ___ Kinder: Anna und Tom.',a:'zwei',o:['zweite','zweimal','zwanzig'],
 ex:'A plain count uses the cardinal number zwei; zweite means „second“.',tr:'I have two children: Anna and Tom.',say:'Ich habe zwei Kinder: Anna und Tom.'},
{gid:'numbers',lv:1,sk:'Numbers',s:'„Wie viel kostet das?“ — „___ Euro.“ (15)',a:'fünfzehn',o:['fünfzig','fünfundzehn','funfzehn'],
 ex:'15 = fünfzehn; fünfzig is 50, and funfzehn forgets the Umlaut.',tr:'„How much is that?“ — „Fifteen euros.“',say:'Das kostet fünfzehn Euro.'},

/* ---- articles ---- */
{gid:'articles',lv:2,sk:'Articles',s:'___ Mann ist groß.',a:'Der',o:['Die','Das','Den'],
 ex:'Mann is masculine → der Mann, and the subject stays in the Nominative.',tr:'The man is tall.',say:'Der Mann ist groß.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Frau liest ein Buch.',a:'Die',o:['Der','Das','Dem'],
 ex:'Frau is feminine → die Frau.',tr:'The woman is reading a book.',say:'Die Frau liest ein Buch.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Kind schläft.',a:'Das',o:['Der','Die','Den'],
 ex:'Kind is neuter → das Kind.',tr:'The child is sleeping.',say:'Das Kind schläft.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Kinder spielen draußen.',a:'Die',o:['Der','Das','Dem'],
 ex:'The plural article is die for all three genders.',tr:'The children are playing outside.',say:'Die Kinder spielen draußen.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Wohnung ist klein.',a:'Die',o:['Der','Das','Den'],
 ex:'Nouns in -ung are always feminine → die Wohnung.',tr:'The flat is small.',say:'Die Wohnung ist klein.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Mädchen heißt Lena.',a:'Das',o:['Die','Der','Dem'],
 ex:'The ending -chen makes a noun neuter → das Mädchen, although it means a girl.',tr:'The girl is called Lena.',say:'Das Mädchen heißt Lena.'},
{gid:'articles',lv:2,sk:'Articles',s:'___ Montag ist mein freier Tag.',a:'Der',o:['Die','Das','Dem'],
 ex:'Days, months and seasons are masculine → der Montag.',tr:'Monday is my day off.',say:'Der Montag ist mein freier Tag.'},
{gid:'articles',lv:2,sk:'Articles',s:'Das ist ___ Haus, und dort ist die Schule.',a:'das',o:['der','die','dem'],
 ex:'Haus is neuter → das Haus; after „Das ist“ the noun is still Nominative.',tr:'That is the house, and over there is the school.',say:'Das ist das Haus, und dort ist die Schule.'},

/* ---- pronouns ---- */
{gid:'pronouns',lv:2,sk:'Verbs',s:'___ bin Student.',a:'Ich',o:['Du','Er','Wir'],
 ex:'The form bin belongs only to ich.',tr:'I am a student.',say:'Ich bin Student.'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Wo wohnst ___ ?',a:'du',o:['Sie','ihr','er'],
 ex:'The ending -st goes with du.',tr:'Where do you live?',say:'Wo wohnst du?'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Anna ist Lehrerin. ___ arbeitet in Berlin.',a:'Sie',o:['Er','Es','Wir'],
 ex:'Anna is one female person → sie (she).',tr:'Anna is a teacher. She works in Berlin.',say:'Anna ist Lehrerin. Sie arbeitet in Berlin.'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Das Kind ist müde. ___ schläft jetzt.',a:'Es',o:['Er','Sie','Ihr'],
 ex:'das Kind is neuter, so the pronoun is es — even for a person.',tr:'The child is tired. It is sleeping now.',say:'Das Kind ist müde. Es schläft jetzt.'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Tom und ich lernen Deutsch. ___ sind im Kurs.',a:'Wir',o:['Sie','Ihr','Er'],
 ex:'„Tom and I“ = wir (we).',tr:'Tom and I are learning German. We are in the course.',say:'Tom und ich lernen Deutsch. Wir sind im Kurs.'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Kinder, wo seid ___ ?',a:'ihr',o:['Sie','du','wir'],
 ex:'seid goes with ihr — the plural „you“ for several friends.',tr:'Children, where are you?',say:'Kinder, wo seid ihr?'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Herr Weber, woher kommen ___ ?',a:'Sie',o:['sie','du','ihr'],
 ex:'A stranger addressed by surname takes the formal Sie, always capitalised.',tr:'Mr Weber, where do you come from?',say:'Herr Weber, woher kommen Sie?'},
{gid:'pronouns',lv:2,sk:'Verbs',s:'Meine Eltern wohnen in Köln. ___ haben ein Haus dort.',a:'Sie',o:['Er','Es','Ihr'],
 ex:'Several people → sie (they); the verb haben confirms the plural.',tr:'My parents live in Cologne. They have a house there.',say:'Meine Eltern wohnen in Köln. Sie haben ein Haus dort.'},

/* ---- present ---- */
{gid:'present',lv:2,sk:'Verbs',s:'Ich ___ Fußball. (spielen)',a:'spiele',o:['spielst','spielt','spielen'],
 ex:'ich takes the ending -e: ich spiele.',tr:'I play football.',say:'Ich spiele Fußball.'},
{gid:'present',lv:2,sk:'Verbs',s:'Du ___ in Berlin. (wohnen)',a:'wohnst',o:['wohne','wohnt','wohnen'],
 ex:'du takes the ending -st: du wohnst.',tr:'You live in Berlin.',say:'Du wohnst in Berlin.'},
{gid:'present',lv:2,sk:'Verbs',s:'Er ___ Deutsch. (lernen)',a:'lernt',o:['lerne','lernst','lernen'],
 ex:'er/sie/es takes the ending -t: er lernt.',tr:'He is learning German.',say:'Er lernt Deutsch.'},
{gid:'present',lv:2,sk:'Verbs',s:'Wir ___ Kaffee. (trinken)',a:'trinken',o:['trinke','trinkst','trinkt'],
 ex:'wir and sie/Sie keep the infinitive ending -en.',tr:'We drink coffee.',say:'Wir trinken Kaffee.'},
{gid:'present',lv:2,sk:'Verbs',s:'Ihr ___ sehr schnell. (arbeiten)',a:'arbeitet',o:['arbeitt','arbeitst','arbeiten'],
 ex:'A stem ending in -t adds an extra e before the ending: ihr arbeitet.',tr:'You work very fast.',say:'Ihr arbeitet sehr schnell.'},
{gid:'present',lv:2,sk:'Verbs',s:'Du ___ gern Bücher. (lesen)',a:'liest',o:['lesst','lest','liesst'],
 ex:'lesen changes e→ie in the du/er forms, and the stem-s merges with -st: du liest.',tr:'You like reading books.',say:'Du liest gern Bücher.'},
{gid:'present',lv:2,sk:'Verbs',s:'Heute ___ wir Deutsch. (lernen)',a:'lernen',o:['lernt','lerne','zu lernen'],
 ex:'The verb stays in position 2 after „Heute“, and wir needs -en.',tr:'Today we are learning German.',say:'Heute lernen wir Deutsch.'},
{gid:'present',lv:2,sk:'Verbs',s:'Mein Bruder und ich ___ oft Tennis. (spielen)',a:'spielen',o:['spielt','spiele','spielst'],
 ex:'„Mein Bruder und ich“ equals wir → spielen, not the singular form.',tr:'My brother and I often play tennis.',say:'Mein Bruder und ich spielen oft Tennis.'},

/* ---- seinhaben ---- */
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Ich ___ müde.',a:'bin',o:['ist','bist','sind'],
 ex:'sein is irregular: ich bin.',tr:'I am tired.',say:'Ich bin müde.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Du ___ sehr nett.',a:'bist',o:['bin','ist','seid'],
 ex:'du bist — the only form with -st in sein.',tr:'You are very nice.',say:'Du bist sehr nett.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Sie ___ Ärztin. (eine Frau)',a:'ist',o:['bin','bist','sind'],
 ex:'One woman = er/sie/es form → sie ist. Note: no article before a profession.',tr:'She is a doctor.',say:'Sie ist Ärztin.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Wir ___ Zeit.',a:'haben',o:['habe','hast','hat'],
 ex:'wir haben — the plural keeps the infinitive form.',tr:'We have time.',say:'Wir haben Zeit.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'___ du Hunger?',a:'Hast',o:['Habt','Hat','Habe'],
 ex:'du hast; in a yes/no question the verb simply moves to the front.',tr:'Are you hungry?',say:'Hast du Hunger?'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Ihr ___ zu spät.',a:'seid',o:['sind','seit','bist'],
 ex:'ihr seid is written with d; „seit“ with t is the preposition „since“.',tr:'You are too late.',say:'Ihr seid zu spät.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Mein Bruder ___ zwei Kinder.',a:'hat',o:['haben','habt','ist'],
 ex:'er/sie/es → hat; sein could never take an object like „zwei Kinder“.',tr:'My brother has two children.',say:'Mein Bruder hat zwei Kinder.'},
{gid:'seinhaben',lv:2,sk:'Verbs',s:'Das ___ meine Eltern.',a:'sind',o:['ist','sein','bin'],
 ex:'The real subject is plural (meine Eltern), so sein takes sind even after „Das“.',tr:'These are my parents.',say:'Das sind meine Eltern.'},

/* ---- wordorder ---- */
{gid:'wordorder',lv:2,sk:'Sentences',s:'Heute ___ ich Deutsch.',a:'lerne',o:['ich lerne','lernen','lerne ich'],
 ex:'The conjugated verb is the second element: Heute (1) lerne (2) ich.',tr:'Today I am learning German.',say:'Heute lerne ich Deutsch.'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'Morgen ___ wir nach Berlin.',a:'fahren',o:['wir fahren','fahren wir','zu fahren'],
 ex:'„Morgen“ fills position 1, so the verb comes next and the subject follows it.',tr:'Tomorrow we are travelling to Berlin.',say:'Morgen fahren wir nach Berlin.'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'___ du Deutsch?',a:'Lernst',o:['Du lernst','Lernen','Lernt'],
 ex:'A yes/no question puts the conjugated verb in first place.',tr:'Are you learning German?',say:'Lernst du Deutsch?'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'Wo ___ du?',a:'wohnst',o:['du wohnst','wohnen','wohnt'],
 ex:'After a W-word the verb comes next, then the subject.',tr:'Where do you live?',say:'Wo wohnst du?'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'Wann ___ der Zug?',a:'kommt',o:['der Zug kommt','kommen','zu kommen'],
 ex:'Wann (1) kommt (2) der Zug — the verb keeps position 2.',tr:'When does the train come?',say:'Wann kommt der Zug?'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'Was ___ du am Wochenende?',a:'machst',o:['du machst','machen','macht'],
 ex:'W-word, then verb, then subject — and du needs -st.',tr:'What are you doing at the weekend?',say:'Was machst du am Wochenende?'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'In den Ferien ___ meine Familie immer ans Meer.',a:'fährt',o:['meine Familie fährt','fahren','fahrt'],
 ex:'Position 1 holds the time phrase, position 2 the verb — and Familie is singular → fährt.',tr:'In the holidays my family always goes to the sea.',say:'In den Ferien fährt meine Familie immer ans Meer.'},
{gid:'wordorder',lv:2,sk:'Sentences',s:'Deutsch ___ ich jeden Tag.',a:'lerne',o:['lernen','ich lerne','lerne ich'],
 ex:'Even the object may fill position 1 — the verb still stands second and the subject follows.',tr:'German I study every day.',say:'Deutsch lerne ich jeden Tag.'},

/* ---- nomakk ---- */
{gid:'nomakk',lv:3,sk:'Cases',s:'Ich sehe ___ Hund.',a:'den',o:['der','dem','des'],
 ex:'Masculine Akkusativ: der → den. Only the masculine article changes.',tr:'I see the dog.',say:'Ich sehe den Hund.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Der Mann liest ___ Buch.',a:'das',o:['dem','des','der'],
 ex:'Neuter stays the same in the Akkusativ: das Buch.',tr:'The man is reading the book.',say:'Der Mann liest das Buch.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Ich kaufe ___ Apfel.',a:'einen',o:['ein','einem','eines'],
 ex:'Masculine indefinite Akkusativ: ein → einen.',tr:'I am buying an apple.',say:'Ich kaufe einen Apfel.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'___ Frau sieht den Mann.',a:'Die',o:['Der','Den','Dem'],
 ex:'The subject is Nominative, and feminine stays die.',tr:'The woman sees the man.',say:'Die Frau sieht den Mann.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Ich brauche ___ Lampe.',a:'eine',o:['einen','ein','einem'],
 ex:'Lampe is feminine → eine, identical in Nominative and Akkusativ.',tr:'I need a lamp.',say:'Ich brauche eine Lampe.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Den Hund sieht ___ Mann.',a:'der',o:['den','dem','des'],
 ex:'„den Hund“ is already marked as the object, so Mann must be the Nominative subject.',tr:'The man sees the dog. (object first)',say:'Den Hund sieht der Mann.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Ich sehe ___ Kinder im Garten.',a:'die',o:['den','dem','der'],
 ex:'Plural Akkusativ is die, unchanged from the Nominative.',tr:'I see the children in the garden.',say:'Ich sehe die Kinder im Garten.'},
{gid:'nomakk',lv:3,sk:'Cases',s:'Ich rufe ___ Bruder an.',a:'meinen',o:['mein','meinem','meines'],
 ex:'Possessives take ein-endings, so masculine Akkusativ → meinen Bruder.',tr:'I am calling my brother.',say:'Ich rufe meinen Bruder an.'},

/* ---- dativ ---- */
{gid:'dativ',lv:3,sk:'Cases',s:'Ich helfe ___ Mann.',a:'dem',o:['den','der','des'],
 ex:'helfen takes the Dativ → dem Mann.',tr:'I am helping the man.',say:'Ich helfe dem Mann.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Das Buch gehört ___ Frau.',a:'der',o:['die','dem','des'],
 ex:'Feminine Dativ: die → der.',tr:'The book belongs to the woman.',say:'Das Buch gehört der Frau.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Ich gebe ___ Kind einen Ball.',a:'dem',o:['das','den','des'],
 ex:'Neuter Dativ: das → dem; the receiver is the indirect object.',tr:'I give the child a ball.',say:'Ich gebe dem Kind einen Ball.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Wir danken ___ Lehrern für die Hilfe.',a:'den',o:['die','dem','der'],
 ex:'Plural Dativ: die → den, and the noun itself adds -n (Lehrern).',tr:'We thank the teachers for their help.',say:'Wir danken den Lehrern für die Hilfe.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Das Bild gefällt ___ sehr.',a:'mir',o:['mich','ich','mein'],
 ex:'gefallen takes the Dativ → mir, never mich.',tr:'I like the picture a lot.',say:'Das Bild gefällt mir sehr.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Antworte bitte ___ Kollegin!',a:'der',o:['die','dem','den'],
 ex:'antworten is a Dativ verb and Kollegin is feminine → der Kollegin.',tr:'Please answer your colleague!',say:'Antworte bitte der Kollegin!'},
{gid:'dativ',lv:3,sk:'Cases',s:'Ich schenke ___ Vater eine Uhr.',a:'meinem',o:['meinen','mein','meines'],
 ex:'The person is Dativ (meinem Vater), the thing Akkusativ (eine Uhr).',tr:'I am giving my father a watch.',say:'Ich schenke meinem Vater eine Uhr.'},
{gid:'dativ',lv:3,sk:'Cases',s:'Ich fahre mit ___ Bus zur Schule.',a:'dem',o:['den','der','das'],
 ex:'mit always takes the Dativ → mit dem Bus.',tr:'I go to school by bus.',say:'Ich fahre mit dem Bus zur Schule.'},

/* ---- plural ---- */
{gid:'plural',lv:3,sk:'Plurals',s:'ein Tisch → zwei ___',a:'Tische',o:['Tischen','Tischer','Tisches'],
 ex:'der Tisch takes -e in the plural: die Tische.',tr:'one table → two tables',say:'ein Tisch, zwei Tische'},
{gid:'plural',lv:3,sk:'Plurals',s:'ein Kind → drei ___',a:'Kinder',o:['Kinde','Kindern','Kinds'],
 ex:'das Kind takes -er: die Kinder. Kindern is only the Dativ plural.',tr:'one child → three children',say:'ein Kind, drei Kinder'},
{gid:'plural',lv:3,sk:'Plurals',s:'eine Frau → vier ___',a:'Frauen',o:['Fraus','Fraue','Frauer'],
 ex:'Feminine nouns almost always add -en: die Frauen.',tr:'one woman → four women',say:'eine Frau, vier Frauen'},
{gid:'plural',lv:3,sk:'Plurals',s:'ein Auto → fünf ___',a:'Autos',o:['Auten','Autoe','Autoer'],
 ex:'Borrowed words often take -s: die Autos.',tr:'one car → five cars',say:'ein Auto, fünf Autos'},
{gid:'plural',lv:3,sk:'Plurals',s:'ein Vater → zwei ___',a:'Väter',o:['Vaters','Vatere','Vatern'],
 ex:'Some nouns change only the vowel: der Vater → die Väter.',tr:'one father → two fathers',say:'ein Vater, zwei Väter'},
{gid:'plural',lv:3,sk:'Plurals',s:'ein Apfel → drei ___',a:'Äpfel',o:['Apfeln','Apfels','Äpfeln'],
 ex:'Umlaut only: der Apfel → die Äpfel; Äpfeln would be the Dativ plural.',tr:'one apple → three apples',say:'ein Apfel, drei Äpfel'},
{gid:'plural',lv:3,sk:'Plurals',s:'___ Bücher sind teuer.',a:'Die',o:['Der','Das','Dem'],
 ex:'Every plural takes die — and das Buch becomes die Bücher.',tr:'The books are expensive.',say:'Die Bücher sind teuer.'},
{gid:'plural',lv:3,sk:'Plurals',s:'Ich spreche mit den ___ .',a:'Kindern',o:['Kinder','Kinde','Kinders'],
 ex:'In the Dativ plural the noun itself adds -n: mit den Kindern.',tr:'I am talking to the children.',say:'Ich spreche mit den Kindern.'},

/* ---- modals ---- */
{gid:'modals',lv:3,sk:'Verbs',s:'Ich ___ gut schwimmen.',a:'kann',o:['kannst','können','kanne'],
 ex:'können: ich kann, with no ending at all.',tr:'I can swim well.',say:'Ich kann gut schwimmen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Du ___ jetzt gehen.',a:'musst',o:['muss','müsst','müssen'],
 ex:'du musst — the du-form of a modal is the only one with -st.',tr:'You have to go now.',say:'Du musst jetzt gehen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Wir ___ Pizza essen.',a:'wollen',o:['will','wollt','willst'],
 ex:'wir wollen; the infinitive essen closes the sentence.',tr:'We want to eat pizza.',say:'Wir wollen Pizza essen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Hier ___ man nicht rauchen.',a:'darf',o:['darfst','dürfen','dürft'],
 ex:'man counts as er/sie/es → darf.',tr:'You may not smoke here.',say:'Hier darf man nicht rauchen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Er ___ heute länger arbeiten.',a:'muss',o:['musst','müssen','mussen'],
 ex:'ich and er have the same modal form: er muss, with no -t.',tr:'He has to work longer today.',say:'Er muss heute länger arbeiten.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Ich kann sehr gut ___ .',a:'kochen',o:['koche','gekocht','zu kochen'],
 ex:'A modal sends the main verb to the end as a plain infinitive — never with zu.',tr:'I can cook very well.',say:'Ich kann sehr gut kochen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Morgen ___ ich früher aufstehen.',a:'muss',o:['musste','müssen','muss zu'],
 ex:'The modal takes position 2 after „Morgen“, and aufstehen closes the sentence.',tr:'Tomorrow I have to get up earlier.',say:'Morgen muss ich früher aufstehen.'},
{gid:'modals',lv:3,sk:'Verbs',s:'Ich ___ heute leider nicht kommen.',a:'kann',o:['kannst','können','gekonnt'],
 ex:'ich kann, and nicht stands directly before the infinitive kommen.',tr:'Unfortunately I cannot come today.',say:'Ich kann heute leider nicht kommen.'},

/* ---- separable ---- */
{gid:'separable',lv:3,sk:'Verbs',s:'Ich stehe um sieben Uhr ___ . (aufstehen)',a:'auf',o:['an','aus','ein'],
 ex:'The prefix of aufstehen splits off and closes the sentence: … auf.',tr:'I get up at seven.',say:'Ich stehe um sieben Uhr auf.'},
{gid:'separable',lv:3,sk:'Verbs',s:'Wir kaufen im Supermarkt ___ . (einkaufen)',a:'ein',o:['auf','an','aus'],
 ex:'einkaufen → kaufen … ein, with the prefix at the very end.',tr:'We do our shopping at the supermarket.',say:'Wir kaufen im Supermarkt ein.'},
{gid:'separable',lv:3,sk:'Verbs',s:'Er ruft dich später ___ . (anrufen)',a:'an',o:['auf','ein','ab'],
 ex:'anrufen → ruft … an.',tr:'He will call you later.',say:'Er ruft dich später an.'},
{gid:'separable',lv:3,sk:'Verbs',s:'Der Zug fährt um acht Uhr ___ . (abfahren)',a:'ab',o:['auf','an','aus'],
 ex:'abfahren → fährt … ab.',tr:'The train leaves at eight.',say:'Der Zug fährt um acht Uhr ab.'},
{gid:'separable',lv:3,sk:'Verbs',s:'Kommst du heute Abend ___ ? (mitkommen)',a:'mit',o:['an','auf','aus'],
 ex:'mitkommen → kommst … mit; in a question the prefix still goes last.',tr:'Are you coming along this evening?',say:'Kommst du heute Abend mit?'},
{gid:'separable',lv:3,sk:'Verbs',s:'Wann ___ der Film an?',a:'fängt',o:['anfängt','fangen','fängt an'],
 ex:'Only the conjugated part moves forward; the prefix an stays at the end.',tr:'When does the film start?',say:'Wann fängt der Film an?'},
{gid:'separable',lv:3,sk:'Verbs',s:'Ich muss morgen früh ___ .',a:'aufstehen',o:['aufstehe','steh auf','auf stehen'],
 ex:'After a modal the separable verb stays whole at the end: aufstehen.',tr:'I have to get up early tomorrow.',say:'Ich muss morgen früh aufstehen.'},
{gid:'separable',lv:3,sk:'Verbs',s:'Ich rufe dich heute nicht ___ .',a:'an',o:['auf','ab','ein'],
 ex:'nicht comes before the prefix, which still closes the sentence: … nicht an.',tr:'I am not going to call you today.',say:'Ich rufe dich heute nicht an.'},

/* ---- perfekt ---- */
{gid:'perfekt',lv:3,sk:'Verbs',s:'Ich ___ Fußball gespielt.',a:'habe',o:['bin','hat','habt'],
 ex:'spielen takes haben → ich habe … gespielt.',tr:'I played football.',say:'Ich habe Fußball gespielt.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Wir ___ nach Berlin gefahren.',a:'sind',o:['haben','sein','ist'],
 ex:'Verbs of movement take sein → wir sind gefahren.',tr:'We drove to Berlin.',say:'Wir sind nach Berlin gefahren.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Sie hat einen Kuchen ___ . (backen)',a:'gebacken',o:['gebackt','backen','backte'],
 ex:'backen is strong: the participle is gebacken, not „gebackt“.',tr:'She baked a cake.',say:'Sie hat einen Kuchen gebacken.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Ich habe gestern viel ___ . (arbeiten)',a:'gearbeitet',o:['gearbeitt','arbeitete','gearbeiten'],
 ex:'Regular participle ge- + stem + -t, with an extra e after the -t: gearbeitet.',tr:'I worked a lot yesterday.',say:'Ich habe gestern viel gearbeitet.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Er ___ gestern zu Hause geblieben.',a:'ist',o:['hat','war','sind'],
 ex:'bleiben is a change-of-state verb and takes sein: er ist geblieben.',tr:'He stayed at home yesterday.',say:'Er ist gestern zu Hause geblieben.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Hast du das Buch ___ ? (lesen)',a:'gelesen',o:['gelest','las','gelesed'],
 ex:'Strong verbs form ge- … -en: gelesen.',tr:'Have you read the book?',say:'Hast du das Buch gelesen?'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Ich bin um sechs Uhr ___ . (aufstehen)',a:'aufgestanden',o:['gestanden auf','aufgestehen','aufstanden'],
 ex:'With separable verbs ge- slips between prefix and stem — and aufstehen takes sein.',tr:'I got up at six.',say:'Ich bin um sechs Uhr aufgestanden.'},
{gid:'perfekt',lv:3,sk:'Verbs',s:'Gestern ___ wir einen Film gesehen.',a:'haben',o:['sind','hat','habt'],
 ex:'The helper verb sits in position 2 and the participle closes the sentence; sehen takes haben.',tr:'Yesterday we watched a film.',say:'Gestern haben wir einen Film gesehen.'},

/* ---- praeteritum ---- */
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Ich ___ gestern krank. (sein)',a:'war',o:['bin','wäre','gewesen'],
 ex:'The Präteritum of sein is war — used even in everyday speech.',tr:'I was ill yesterday.',say:'Ich war gestern krank.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Er ___ keine Zeit. (haben)',a:'hatte',o:['hat','hätte','gehabt'],
 ex:'haben → hatte; hätte with Umlaut would be Konjunktiv II („would have“).',tr:'He had no time.',say:'Er hatte keine Zeit.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Sie ___ nach Hause. (gehen)',a:'ging',o:['gegangen','geht','gangte'],
 ex:'gehen is strong: er/sie ging, with no ending.',tr:'She went home.',say:'Sie ging nach Hause.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Wir ___ um acht Uhr an. (ankommen)',a:'kamen',o:['kommen','gekommen','kamten'],
 ex:'kommen → kam, plural wir kamen; the prefix an still closes the sentence.',tr:'We arrived at eight.',say:'Wir kamen um acht Uhr an.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Das Kind ___ den Film nicht. (sehen)',a:'sah',o:['sehte','gesehen','seh'],
 ex:'sehen is strong: er sah.',tr:'The child did not see the film.',say:'Das Kind sah den Film nicht.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Früher ___ ich jeden Tag Klavier. (spielen)',a:'spielte',o:['spielt','gespielt','spielten'],
 ex:'Regular verbs insert -te: ich spielte.',tr:'I used to play the piano every day.',say:'Früher spielte ich jeden Tag Klavier.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Im Gespräch sagt man lieber: „Ich ___ gegessen.“',a:'habe',o:['aß','esse','hatte'],
 ex:'Everyday speech prefers the Perfekt for most verbs: „Ich habe gegessen“, not „Ich aß“.',tr:'In conversation you would rather say „I have eaten“.',say:'Ich habe gegessen.'},
{gid:'praeteritum',lv:4,sk:'Verbs',s:'Als ich klein ___ , wohnten wir in Köln.',a:'war',o:['bin','wäre','gewesen'],
 ex:'sein keeps its Präteritum even in speech, and in the als-clause the verb goes last.',tr:'When I was small we lived in Cologne.',say:'Als ich klein war, wohnten wir in Köln.'},

/* ---- prepositions ---- */
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Ich gehe in ___ Schule. (Bewegung)',a:'die',o:['der','dem','den'],
 ex:'in + motion (wohin?) → Akkusativ: in die Schule.',tr:'I am going into the school.',say:'Ich gehe in die Schule.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Ich bin in ___ Schule. (Ort)',a:'der',o:['die','das','den'],
 ex:'in + location (wo?) → Dativ: in der Schule.',tr:'I am in the school.',say:'Ich bin in der Schule.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Das Geschenk ist für ___ .',a:'dich',o:['dir','du','dein'],
 ex:'für always takes the Akkusativ → für dich.',tr:'The present is for you.',say:'Das Geschenk ist für dich.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Ich fahre mit ___ Zug.',a:'dem',o:['den','der','des'],
 ex:'mit always takes the Dativ → mit dem Zug.',tr:'I am travelling by train.',say:'Ich fahre mit dem Zug.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Wir gehen ohne ___ Hund spazieren.',a:'den',o:['dem','der','des'],
 ex:'ohne + Akkusativ, masculine → ohne den Hund.',tr:'We are going for a walk without the dog.',say:'Wir gehen ohne den Hund spazieren.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Nach ___ Essen trinken wir Kaffee.',a:'dem',o:['das','des','den'],
 ex:'nach belongs to the fixed Dativ group (aus, bei, mit, nach, seit, von, zu).',tr:'After the meal we drink coffee.',say:'Nach dem Essen trinken wir Kaffee.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Ich hänge das Bild an ___ Wand.',a:'die',o:['der','dem','den'],
 ex:'hängen with motion (wohin?) → Akkusativ: an die Wand. „an der Wand“ is where it already hangs.',tr:'I am hanging the picture on the wall.',say:'Ich hänge das Bild an die Wand.'},
{gid:'prepositions',lv:4,sk:'Prepositions',s:'Das Buch liegt auf ___ Tisch.',a:'dem',o:['den','der','des'],
 ex:'liegen describes a position (wo?) → Dativ: auf dem Tisch.',tr:'The book is lying on the table.',say:'Das Buch liegt auf dem Tisch.'},

/* ---- adjektiv ---- */
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Das ist der ___ Apfel. (rot)',a:'rote',o:['roten','roter','rotes'],
 ex:'After der in the masculine Nominative the ending is -e: der rote Apfel.',tr:'That is the red apple.',say:'Das ist der rote Apfel.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Ich sehe den ___ Apfel. (rot)',a:'roten',o:['rote','roter','rotes'],
 ex:'Masculine Akkusativ after den takes -en: den roten Apfel.',tr:'I see the red apple.',say:'Ich sehe den roten Apfel.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Die ___ Frau wartet draußen. (jung)',a:'junge',o:['jungen','junger','junges'],
 ex:'Feminine Nominative after die → -e: die junge Frau.',tr:'The young woman is waiting outside.',say:'Die junge Frau wartet draußen.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Ich fahre mit dem ___ Auto. (neu)',a:'neuen',o:['neue','neues','neuer'],
 ex:'Every Dativ after a der-word takes -en: mit dem neuen Auto.',tr:'I drive the new car.',say:'Ich fahre mit dem neuen Auto.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Das ___ Kind schläft. (klein)',a:'kleine',o:['kleinen','kleines','kleiner'],
 ex:'Neuter Nominative after das → -e: das kleine Kind.',tr:'The small child is sleeping.',say:'Das kleine Kind schläft.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Ich mag die ___ Bücher. (alt)',a:'alten',o:['alte','altes','alter'],
 ex:'Plural after die always takes -en, in the Nominative and the Akkusativ alike.',tr:'I like the old books.',say:'Ich mag die alten Bücher.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Ich habe das ___ Buch gelesen. (spannend)',a:'spannende',o:['spannenden','spannendes','spannender'],
 ex:'Neuter Akkusativ after das is still -e — only the masculine switches to -en.',tr:'I have read the exciting book.',say:'Ich habe das spannende Buch gelesen.'},
{gid:'adjektiv',lv:4,sk:'Adjectives',s:'Wir wohnen in der ___ Stadt. (groß)',a:'großen',o:['große','großes','großer'],
 ex:'in + wo? → Dativ, and every Dativ after a der-word takes -en.',tr:'We live in the big city.',say:'Wir wohnen in der großen Stadt.'},

/* ---- komparativ ---- */
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Anna ist ___ als Tom. (groß)',a:'größer',o:['großer','mehr groß','am größten'],
 ex:'Comparative = adjective + -er, here with Umlaut: größer. German never uses „mehr“ for this.',tr:'Anna is taller than Tom.',say:'Anna ist größer als Tom.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Mein Auto ist ___ als dein Auto. (alt)',a:'älter',o:['alter','mehr alt','am ältesten'],
 ex:'Short adjectives often add an Umlaut: alt → älter.',tr:'My car is older than your car.',say:'Mein Auto ist älter als dein Auto.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Das ist das ___ Buch, das ich kenne. (gut)',a:'beste',o:['guteste','gutste','bessere'],
 ex:'gut is irregular: gut → besser → das beste.',tr:'That is the best book I know.',say:'Das ist das beste Buch, das ich kenne.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Tom läuft ___ als ich. (schnell)',a:'schneller',o:['schnellerer','mehr schnell','am schnellsten'],
 ex:'Adverbs form the comparative the same way: schneller als ich.',tr:'Tom runs faster than me.',say:'Tom läuft schneller als ich.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Ich arbeite ___ am Morgen. (gut)',a:'am besten',o:['besser','der beste','am guten'],
 ex:'The superlative of an adverb is am + -sten; gut is irregular → am besten.',tr:'I work best in the morning.',say:'Ich arbeite am besten am Morgen.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Ich trinke ___ Tee als Kaffee. (gern)',a:'lieber',o:['gerner','mehr gern','am liebsten'],
 ex:'gern is irregular: gern → lieber → am liebsten.',tr:'I prefer tea to coffee.',say:'Ich trinke lieber Tee als Kaffee.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Ich nehme das ___ Zimmer. (billig, Superlativ)',a:'billigste',o:['billigsten','billigere','am billigsten'],
 ex:'Before a noun the superlative takes an adjective ending: das billigste Zimmer.',tr:'I will take the cheapest room.',say:'Ich nehme das billigste Zimmer.'},
{gid:'komparativ',lv:4,sk:'Adjectives',s:'Mein Bruder ist so groß ___ ich.',a:'wie',o:['als','denn','dass'],
 ex:'Equality uses so … wie; als is only for a real comparison (größer als ich).',tr:'My brother is as tall as me.',say:'Mein Bruder ist so groß wie ich.'},

/* ---- konjunktiv ---- */
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Ich ___ gern einen Kaffee.',a:'hätte',o:['habe','hatte','haben'],
 ex:'„Ich hätte gern …“ is the polite Konjunktiv II of haben — the standard way to order.',tr:'I would like a coffee.',say:'Ich hätte gern einen Kaffee.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'___ Sie mir bitte helfen?',a:'Könnten',o:['Konnten','Können','Kennen'],
 ex:'Könnten with Umlaut is the polite Konjunktiv II; konnten without it is the past indicative.',tr:'Could you help me, please?',say:'Könnten Sie mir bitte helfen?'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Wenn ich reich ___ , würde ich reisen.',a:'wäre',o:['war','bin','werde'],
 ex:'An unreal condition takes wäre, the Konjunktiv II of sein.',tr:'If I were rich I would travel.',say:'Wenn ich reich wäre, würde ich reisen.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Wenn ich Zeit hätte, ___ ich mitkommen.',a:'würde',o:['werde','wurde','will'],
 ex:'The main clause uses würde + infinitive: würde … mitkommen.',tr:'If I had time I would come along.',say:'Wenn ich Zeit hätte, würde ich mitkommen.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Ich ___ gern wissen, was passiert ist.',a:'möchte',o:['mag','mochte','will'],
 ex:'möchte is the Konjunktiv II of mögen and the polite way to say „I would like“.',tr:'I would like to know what happened.',say:'Ich möchte gern wissen, was passiert ist.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Hätte ich das gewusst, ___ ich zu Hause geblieben.',a:'wäre',o:['hätte','würde','war'],
 ex:'bleiben takes sein, so the past unreal is wäre … geblieben.',tr:'If I had known that I would have stayed at home.',say:'Hätte ich das gewusst, wäre ich zu Hause geblieben.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'Wenn du mich gefragt ___ , hätte ich dir geholfen.',a:'hättest',o:['hast','hättst','würdest'],
 ex:'Past unreal = hätte + Partizip II; the du-form is hättest.',tr:'If you had asked me I would have helped you.',say:'Wenn du mich gefragt hättest, hätte ich dir geholfen.'},
{gid:'konjunktiv',lv:5,sk:'Verbs',s:'An deiner Stelle ___ ich zum Arzt gehen.',a:'würde',o:['werde','wurde','will'],
 ex:'„An deiner Stelle“ + Konjunktiv II is the standard way to give advice: würde … gehen.',tr:'In your place I would go to the doctor.',say:'An deiner Stelle würde ich zum Arzt gehen.'},

/* ---- passiv ---- */
{gid:'passiv',lv:5,sk:'Verbs',s:'Das Haus ___ gerade gebaut.',a:'wird',o:['ist','wurde','werden'],
 ex:'Present passive = wird + Partizip II.',tr:'The house is being built right now.',say:'Das Haus wird gerade gebaut.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Das Haus ___ 1920 gebaut.',a:'wurde',o:['wird','ist','war'],
 ex:'Past passive = wurde + Partizip II.',tr:'The house was built in 1920.',say:'Das Haus wurde 1920 gebaut.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Der Brief wurde von Anna ___ . (schreiben)',a:'geschrieben',o:['schreiben','geschreibt','schrieb'],
 ex:'The passive always uses the Partizip II: geschrieben.',tr:'The letter was written by Anna.',say:'Der Brief wurde von Anna geschrieben.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Die Fenster ___ jeden Monat geputzt.',a:'werden',o:['wird','wurde','sind'],
 ex:'A plural subject takes werden: die Fenster werden geputzt.',tr:'The windows are cleaned every month.',say:'Die Fenster werden jeden Monat geputzt.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Der Vertrag wurde ___ Chef unterschrieben.',a:'vom',o:['von','von der','durch'],
 ex:'The agent takes von + Dativ, and von dem contracts to vom.',tr:'The contract was signed by the boss.',say:'Der Vertrag wurde vom Chef unterschrieben.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Ich ___ gestern ins Krankenhaus gebracht.',a:'wurde',o:['wurd','war','habe'],
 ex:'Past passive with ich: ich wurde … gebracht.',tr:'I was taken to hospital yesterday.',say:'Ich wurde gestern ins Krankenhaus gebracht.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Diese Regel muss ___ werden. (beachten)',a:'beachtet',o:['beachten','zu beachten','beachtete'],
 ex:'Modal + passive = Partizip II + werden: muss beachtet werden.',tr:'This rule must be observed.',say:'Diese Regel muss beachtet werden.'},
{gid:'passiv',lv:5,sk:'Verbs',s:'Die Tür ist gerade geöffnet ___ .',a:'worden',o:['geworden','werden','gewesen'],
 ex:'In the Perfekt passive the participle of werden is worden, never geworden.',tr:'The door has just been opened.',say:'Die Tür ist gerade geöffnet worden.'},

/* ---- nebensatz ---- */
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Ich bleibe zu Hause, weil ich ___ .',a:'krank bin',o:['bin krank','krank sein','bin ich krank'],
 ex:'weil sends the conjugated verb to the very end: … weil ich krank bin.',tr:'I am staying at home because I am ill.',say:'Ich bleibe zu Hause, weil ich krank bin.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Ich weiß, dass du ___ .',a:'recht hast',o:['hast recht','recht haben','du recht hast'],
 ex:'dass is subordinating, so hast moves to the end.',tr:'I know that you are right.',say:'Ich weiß, dass du recht hast.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Wenn es regnet, ___ wir hier.',a:'bleiben',o:['wir bleiben','bleiben wir','zu bleiben'],
 ex:'The wenn-clause fills position 1, so the main verb follows the comma immediately.',tr:'If it rains we will stay here.',say:'Wenn es regnet, bleiben wir hier.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Obwohl es kalt ___ , gehen wir spazieren.',a:'ist',o:['ist es','sein','es ist'],
 ex:'obwohl is subordinating → the verb goes last in its clause.',tr:'Although it is cold we are going for a walk.',say:'Obwohl es kalt ist, gehen wir spazieren.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Ich hoffe, dass du morgen ___ .',a:'kommst',o:['kommst du','kommen','zu kommen'],
 ex:'In the dass-clause the conjugated verb stands at the end: … dass du morgen kommst.',tr:'I hope that you will come tomorrow.',say:'Ich hoffe, dass du morgen kommst.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Er sagt, dass er keine Zeit ___ .',a:'hat',o:['hat er','haben','er hat'],
 ex:'Verb last: … dass er keine Zeit hat.',tr:'He says that he has no time.',say:'Er sagt, dass er keine Zeit hat.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Ich komme nicht, weil ich arbeiten ___ .',a:'muss',o:['muss arbeiten','müssen','ich muss'],
 ex:'In a subordinate clause the modal goes right to the end, behind the infinitive.',tr:'I am not coming because I have to work.',say:'Ich komme nicht, weil ich arbeiten muss.'},
{gid:'nebensatz',lv:5,sk:'Sentences',s:'Ich bin müde, weil ich schlecht ___ .',a:'geschlafen habe',o:['habe geschlafen','geschlafen bin','habe ich geschlafen'],
 ex:'In the Nebensatz the helper verb moves behind the participle: … geschlafen habe.',tr:'I am tired because I slept badly.',say:'Ich bin müde, weil ich schlecht geschlafen habe.'},

/* ---- aussprache ---- */
{gid:'aussprache',lv:1,sk:'Listening',s:'Der Buchstabe „w“ in „Wasser“ klingt wie englisches ___ .',a:'v',o:['w','f','b'],
 ex:'German w is always the English v sound: Wasser, Wein, wir.',tr:'The letter „w“ in „Wasser“ sounds like English v.',say:'Der Buchstabe „w“ in „Wasser“ klingt wie englisches v.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'Der Buchstabe „v“ in „Vater“ klingt wie ___ .',a:'f',o:['v','w','b'],
 ex:'German v is normally f: Vater, vier, von, verstehen.',tr:'The letter „v“ in „Vater“ sounds like f.',say:'Der Buchstabe „v“ in „Vater“ klingt wie f.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'Das „z“ in „Zeit“ klingt wie ___ .',a:'ts',o:['z','s','sch'],
 ex:'z is always ts: Zeit, Zahn, zehn.',tr:'The „z“ in „Zeit“ sounds like ts.',say:'Das „z“ in „Zeit“ klingt wie ts.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'Am Wortanfang klingen die Buchstaben ___ wie „sht“.',a:'st-',o:['sch-','ch-','ts-'],
 ex:'st- at the beginning of a word is spoken „sht“: Stadt, Stein, Student.',tr:'At the start of a word the letters st- sound like „sht“.',say:'Am Wortanfang klingen die Buchstaben st- wie „sht“.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'„sp“ am Wortanfang klingt wie ___ .',a:'shp',o:['sp','sb','shb'],
 ex:'sp- at the start becomes „shp“: Sport, sprechen, spielen.',tr:'„sp“ at the start of a word sounds like „shp“.',say:'„sp“ am Wortanfang klingt wie shp.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'Das „h“ in „gehen“ ist ___ .',a:'stumm',o:['hart','wie ch','wie k'],
 ex:'h after a vowel is silent and only makes the vowel long: gehen, Uhr, Schuhe.',tr:'The „h“ in „gehen“ is silent.',say:'Das „h“ in „gehen“ ist stumm.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'„ei“ in „mein“ klingt wie englisches ___ .',a:'eye',o:['ee','ay','oy'],
 ex:'ei is „eye“, while ie is the long „ee“ (Liebe). The second letter tells you the sound.',tr:'„ei“ in „mein“ sounds like English „eye“.',say:'„ei“ in „mein“ klingt wie englisches eye.'},
{gid:'aussprache',lv:1,sk:'Listening',s:'Die Endung „-ig“ in „richtig“ klingt wie ___ .',a:'-ich',o:['-ig','-ick','-isch'],
 ex:'Final -ig is spoken like the soft ich-sound: richtig, wichtig, billig.',tr:'The ending „-ig“ in „richtig“ sounds like „-ich“.',say:'Die Endung „-ig“ in „richtig“ klingt wie -ich.'},

/* ---- negation ---- */
{gid:'negation',lv:2,sk:'Sentences',s:'Ich habe ___ Zeit.',a:'keine',o:['nicht','kein','keinen'],
 ex:'Zeit is feminine and has no article → keine Zeit.',tr:'I have no time.',say:'Ich habe keine Zeit.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Das ist ___ Auto.',a:'kein',o:['keine','nicht','keinen'],
 ex:'das Auto is neuter with ein → kein Auto, with no ending.',tr:'That is not a car.',say:'Das ist kein Auto.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Ich trinke ___ Kaffee.',a:'keinen',o:['kein','keine','nichts'],
 ex:'Kaffee is masculine and the direct object → Akkusativ keinen.',tr:'I do not drink coffee.',say:'Ich trinke keinen Kaffee.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Das ist ___ mein Problem.',a:'nicht',o:['kein','keine','keins'],
 ex:'A possessive is already there, so you negate with nicht.',tr:'That is not my problem.',say:'Das ist nicht mein Problem.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Es ist ___ teuer.',a:'nicht',o:['kein','keine','nichts'],
 ex:'Adjectives are always negated with nicht.',tr:'It is not expensive.',say:'Es ist nicht teuer.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Ich kenne den Mann ___ .',a:'nicht',o:['kein','keinen','nichts'],
 ex:'With a definite article you use nicht, and it stands at the end of the sentence.',tr:'I do not know the man.',say:'Ich kenne den Mann nicht.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Ich kann heute ___ kommen.',a:'nicht',o:['kein','nichts','keine'],
 ex:'nicht always stands in front of the infinitive: nicht kommen.',tr:'I cannot come today.',say:'Ich kann heute nicht kommen.'},
{gid:'negation',lv:2,sk:'Sentences',s:'Sie wohnt ___ in Köln. (sie ist weggezogen)',a:'nicht mehr',o:['noch nicht','nicht noch','kein mehr'],
 ex:'nicht mehr = no longer; noch nicht would mean „not yet“.',tr:'She no longer lives in Cologne.',say:'Sie wohnt nicht mehr in Köln.'},

/* ---- possessiv ---- */
{gid:'possessiv',lv:2,sk:'Articles',s:'Das ist ___ Bruder. (ich)',a:'mein',o:['meine','meinen','meiner'],
 ex:'der Bruder is masculine Nominative → mein, with no ending.',tr:'That is my brother.',say:'Das ist mein Bruder.'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Das ist ___ Schwester. (ich)',a:'meine',o:['mein','meinen','meiner'],
 ex:'die Schwester is feminine → meine.',tr:'That is my sister.',say:'Das ist meine Schwester.'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Wo sind ___ Schlüssel? (ich)',a:'meine',o:['mein','meinen','meiner'],
 ex:'Plural takes the same -e ending as the feminine: meine Schlüssel.',tr:'Where are my keys?',say:'Wo sind meine Schlüssel?'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Anna zeigt mir ___ Auto.',a:'ihr',o:['ihre','ihren','seine'],
 ex:'Anna is sie → ihr, and das Auto is neuter Akkusativ → no ending.',tr:'Anna is showing me her car.',say:'Anna zeigt mir ihr Auto.'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Haben Sie ___ Ausweis dabei? (formell)',a:'Ihren',o:['ihren','Ihr','deinen'],
 ex:'Formal Sie → Ihr with a capital I; der Ausweis is masculine Akkusativ → Ihren.',tr:'Do you have your ID with you?',say:'Haben Sie Ihren Ausweis dabei?'},
{gid:'possessiv',lv:2,sk:'Articles',s:'___ Wohnung ist im dritten Stock. (wir)',a:'Unsere',o:['Unser','Unseren','Unserem'],
 ex:'die Wohnung is feminine → unsere Wohnung.',tr:'Our flat is on the third floor.',say:'Unsere Wohnung ist im dritten Stock.'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Tom und ___ Mutter kommen heute. (er)',a:'seine',o:['sein','ihre','seiner'],
 ex:'The owner is Tom (sein), but the ending follows the thing owned: die Mutter → seine.',tr:'Tom and his mother are coming today.',say:'Tom und seine Mutter kommen heute.'},
{gid:'possessiv',lv:2,sk:'Articles',s:'Ich rufe ___ Vater an. (du)',a:'deinen',o:['dein','deine','deinem'],
 ex:'der Vater is masculine and the object → Akkusativ deinen.',tr:'I am calling your father.',say:'Ich rufe deinen Vater an.'},

/* ---- wfragen ---- */
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ ist das? — Das ist Herr Weber.',a:'Wer',o:['Wen','Wem','Was'],
 ex:'Wer asks for the Nominative — the subject or the person identified.',tr:'Who is that? — That is Mr Weber.',say:'Wer ist das?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ siehst du dort?',a:'Wen',o:['Wer','Wem','Wessen'],
 ex:'The direct object is Akkusativ → Wen.',tr:'Whom do you see over there?',say:'Wen siehst du dort?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ hilfst du?',a:'Wem',o:['Wen','Wer','Was'],
 ex:'helfen takes the Dativ, so the question word is Wem.',tr:'Whom are you helping?',say:'Wem hilfst du?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ wohnst du?',a:'Wo',o:['Wohin','Woher','Wann'],
 ex:'Wo asks where you are; wohin = where to, woher = where from.',tr:'Where do you live?',say:'Wo wohnst du?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ kommst du? — Aus Spanien.',a:'Woher',o:['Wohin','Wo','Wie'],
 ex:'An origin takes Woher: Woher kommst du?',tr:'Where do you come from? — From Spain.',say:'Woher kommst du?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ Buch liest du?',a:'Welches',o:['Welcher','Welche','Was'],
 ex:'welcher takes der-endings; das Buch is neuter Akkusativ → Welches Buch.',tr:'Which book are you reading?',say:'Welches Buch liest du?'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'„Hast du keine Zeit?“ — „___ , ich habe Zeit!“',a:'Doch',o:['Ja','Nein','Schon'],
 ex:'doch contradicts a negative question — „yes, actually I do“.',tr:'„Don’t you have time?“ — „Yes, I do have time!“',say:'Doch, ich habe Zeit!'},
{gid:'wfragen',lv:2,sk:'Sentences',s:'___ du heute Zeit?',a:'Hast',o:['Habe','Du hast','Haben'],
 ex:'A yes/no question has no W-word: the verb comes first, and du → hast.',tr:'Do you have time today?',say:'Hast du heute Zeit?'},

/* ---- zeitangaben ---- */
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Der Kurs beginnt ___ acht Uhr.',a:'um',o:['am','im','in'],
 ex:'Clock times always take um: um acht Uhr.',tr:'The course starts at eight o’clock.',say:'Der Kurs beginnt um acht Uhr.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Ich arbeite nicht ___ Montag.',a:'am',o:['um','im','an'],
 ex:'Days take am (an + dem): am Montag.',tr:'I do not work on Monday.',say:'Ich arbeite nicht am Montag.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Wir fahren ___ Sommer nach Italien.',a:'im',o:['am','um','in'],
 ex:'Months and seasons take im: im Sommer, im Januar.',tr:'We are going to Italy in the summer.',say:'Wir fahren im Sommer nach Italien.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Mein Geburtstag ist ___ 3. Mai.',a:'am',o:['im','um','an'],
 ex:'Dates take am: am dritten Mai.',tr:'My birthday is on 3 May.',say:'Mein Geburtstag ist am 3. Mai.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Ich wohne ___ zwei Jahren hier.',a:'seit',o:['vor','für','ab'],
 ex:'seit + Dativ with the present tense = „I have been living here for two years“.',tr:'I have been living here for two years.',say:'Ich wohne seit zwei Jahren hier.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'„Halb sieben“ ist ___ .',a:'18:30',o:['19:30','18:00','19:00'],
 ex:'halb sieben = half an hour to seven = 6:30. German counts towards the next hour.',tr:'„Halb sieben“ is 18:30.',say:'Halb sieben ist 18:30.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'„Viertel vor acht“ ist ___ .',a:'19:45',o:['19:15','20:15','20:45'],
 ex:'Viertel vor acht = a quarter before eight = 7:45.',tr:'„Viertel vor acht“ is 19:45.',say:'Viertel vor acht ist 19:45.'},
{gid:'zeitangaben',lv:2,sk:'Numbers',s:'Ich kann ___ Nacht nicht schlafen.',a:'in der',o:['am','in die','im'],
 ex:'The one exception worth memorising: in der Nacht, not „am“.',tr:'I cannot sleep at night.',say:'Ich kann in der Nacht nicht schlafen.'},

/* ---- imperativ ---- */
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ bitte her! (du, kommen)',a:'Komm',o:['Kommst','Kommen','Kommt'],
 ex:'du kommst → drop the -st → Komm!',tr:'Come here, please!',say:'Komm bitte her!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ bitte einen Moment! (du, warten)',a:'Warte',o:['Wart','Wartest','Warten'],
 ex:'A stem ending in -t keeps the -e: Warte!',tr:'Wait a moment, please!',say:'Warte bitte einen Moment!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ den Text laut! (du, lesen)',a:'Lies',o:['Les','Lese','Liest'],
 ex:'du liest → drop -st but keep the e→ie change → Lies!',tr:'Read the text aloud!',say:'Lies den Text laut!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ Sie bitte Platz! (nehmen)',a:'Nehmen',o:['Nehmt','Nimm','Nehme'],
 ex:'The Sie-imperative is infinitive + Sie: Nehmen Sie!',tr:'Please take a seat!',say:'Nehmen Sie bitte Platz!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ die Bücher auf! (ihr, aufmachen)',a:'Macht',o:['Mach','Machen','Machst'],
 ex:'The ihr-imperative is simply the ihr-form without „ihr“: Macht … auf!',tr:'Open your books!',say:'Macht die Bücher auf!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ nicht so nervös! (du, sein)',a:'Sei',o:['Bist','Sein','Seid'],
 ex:'sein is irregular: Sei! (du), Seid! (ihr), Seien Sie! (Sie).',tr:'Don’t be so nervous!',say:'Sei nicht so nervös!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'___ nicht so schnell! (du, fahren)',a:'Fahr',o:['Fähr','Fahrst','Fähre'],
 ex:'a→ä verbs lose the Umlaut in the imperative: Fahr!, never „Fähr!“.',tr:'Don’t drive so fast!',say:'Fahr nicht so schnell!'},
{gid:'imperativ',lv:2,sk:'Verbs',s:'Komm ___ mal mit! (freundliche Einladung)',a:'doch',o:['nicht','sehr','etwa'],
 ex:'doch mal turns a blunt order into a friendly invitation.',tr:'Do come along!',say:'Komm doch mal mit!'},

/* ---- gern ---- */
{gid:'gern',lv:2,sk:'Adjectives',s:'Ich trinke ___ Tee.',a:'gern',o:['gut','mag','viel gern'],
 ex:'gern next to a normal verb says that you like doing something.',tr:'I like drinking tea.',say:'Ich trinke gern Tee.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Tee oder Kaffee? Ich trinke ___ Kaffee.',a:'lieber',o:['gern','am liebsten','mehr gern'],
 ex:'lieber is the comparative of gern and expresses a preference between two things.',tr:'Tea or coffee? I prefer coffee.',say:'Ich trinke lieber Kaffee.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'___ bleibe ich zu Hause.',a:'Am liebsten',o:['Lieber als','Gerner','Am gernsten'],
 ex:'The superlative of gern is am liebsten.',tr:'Most of all I like staying at home.',say:'Am liebsten bleibe ich zu Hause.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Ich ___ Katzen.',a:'mag',o:['gern','mage','habe gern viel'],
 ex:'For a thing or an animal use mögen: Ich mag Katzen.',tr:'I like cats.',say:'Ich mag Katzen.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Ich ___ einen Kaffee, bitte.',a:'möchte',o:['mag','mochte','will gern haben'],
 ex:'möchte means „would like (right now)“ — the polite way to order something.',tr:'I would like a coffee, please.',say:'Ich möchte einen Kaffee, bitte.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Ich arbeite nicht ___ am Wochenende.',a:'gern',o:['lieber','gut','mag'],
 ex:'nicht gern = I don’t like doing it.',tr:'I don’t like working at the weekend.',say:'Ich arbeite nicht gern am Wochenende.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Ich ___ gern die Rechnung.',a:'hätte',o:['habe','bin','will'],
 ex:'„Ich hätte gern …“ is the standard polite request in a shop or café.',tr:'I would like the bill, please.',say:'Ich hätte gern die Rechnung.'},
{gid:'gern',lv:2,sk:'Adjectives',s:'Fährst du ___ mit dem Zug oder mit dem Auto?',a:'lieber',o:['gern','am liebsten','gerner'],
 ex:'A choice between exactly two options takes lieber, the comparative of gern.',tr:'Do you prefer to travel by train or by car?',say:'Fährst du lieber mit dem Zug oder mit dem Auto?'},

/* ---- reflexiv ---- */
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Ich freue ___ auf das Wochenende.',a:'mich',o:['mir','sich','mein'],
 ex:'sich freuen takes the Akkusativ → mich.',tr:'I am looking forward to the weekend.',say:'Ich freue mich auf das Wochenende.'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Erinnerst du ___ an Anna?',a:'dich',o:['dir','sich','du'],
 ex:'sich erinnern takes the Akkusativ → dich.',tr:'Do you remember Anna?',say:'Erinnerst du dich an Anna?'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Wir treffen ___ um acht.',a:'uns',o:['sich','euch','unser'],
 ex:'wir takes uns in both cases — here it also means „each other“.',tr:'We are meeting at eight.',say:'Wir treffen uns um acht.'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Setzen Sie ___ bitte.',a:'sich',o:['sie','Ihnen','euch'],
 ex:'The formal Sie always takes the reflexive sich, written small.',tr:'Please sit down.',say:'Setzen Sie sich bitte.'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Ich putze ___ die Zähne.',a:'mir',o:['mich','sich','meine'],
 ex:'die Zähne is already the Akkusativ object, so the reflexive drops to the Dativ: mir.',tr:'I am brushing my teeth.',say:'Ich putze mir die Zähne.'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Kannst du ___ das vorstellen?',a:'dir',o:['dich','du','deine'],
 ex:'das is the Akkusativ object, so the reflexive is Dativ: dir.',tr:'Can you imagine that?',say:'Kannst du dir das vorstellen?'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Ich interessiere mich ___ Musik.',a:'für',o:['an','auf','über'],
 ex:'sich interessieren goes with für + Akkusativ.',tr:'I am interested in music.',say:'Ich interessiere mich für Musik.'},
{gid:'reflexiv',lv:3,sk:'Verbs',s:'Ich kann ___ nicht entscheiden.',a:'mich',o:['mir','sich','mein'],
 ex:'sich entscheiden takes the Akkusativ, and the pronoun follows the modal directly.',tr:'I cannot make up my mind.',say:'Ich kann mich nicht entscheiden.'},

/* ---- genitiv ---- */
{gid:'genitiv',lv:3,sk:'Cases',s:'Das ist das Auto ___ Bruders.',a:'meines',o:['meinem','meiner','mein'],
 ex:'Masculine Genitiv: meines Bruders, with -s on the noun as well.',tr:'That is my brother’s car.',say:'Das ist das Auto meines Bruders.'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Der Titel ___ Buches ist lang.',a:'des',o:['dem','der','das'],
 ex:'Masculine and neuter Genitiv article is des, and the noun adds -es.',tr:'The title of the book is long.',say:'Der Titel des Buches ist lang.'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Die Farbe ___ Tür gefällt mir.',a:'der',o:['des','dem','die'],
 ex:'Feminine Genitiv: der Tür — and the noun itself gets no ending.',tr:'I like the colour of the door.',say:'Die Farbe der Tür gefällt mir.'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Das Haus ___ Eltern ist alt.',a:'meiner',o:['meines','meinem','meine'],
 ex:'Plural Genitiv takes -er: meiner Eltern.',tr:'My parents’ house is old.',say:'Das Haus meiner Eltern ist alt.'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Wegen ___ Wetters bleiben wir hier.',a:'des',o:['dem','der','das'],
 ex:'wegen takes the Genitiv → wegen des Wetters.',tr:'Because of the weather we are staying here.',say:'Wegen des Wetters bleiben wir hier.'},
{gid:'genitiv',lv:3,sk:'Cases',s:'___ Tasche ist das?',a:'Wessen',o:['Wem','Wer','Wen'],
 ex:'Wessen is the Genitiv question word: whose.',tr:'Whose bag is that?',say:'Wessen Tasche ist das?'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Umgangssprachlich sagt man: „das Haus ___ meinen Eltern“.',a:'von',o:['des','der','dessen'],
 ex:'In speech the Genitiv is often replaced by von + Dativ: von meinen Eltern.',tr:'Colloquially you say „the house of my parents“ with von.',say:'das Haus von meinen Eltern'},
{gid:'genitiv',lv:3,sk:'Cases',s:'Das ist ___ Auto. (Anna)',a:'Annas',o:['Anna’s','von Annas','des Anna'],
 ex:'Names simply take an -s with no apostrophe: Annas Auto.',tr:'That is Anna’s car.',say:'Das ist Annas Auto.'},

/* ---- verbkasus ---- */
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich helfe ___ Kollegen.',a:'dem',o:['den','der','des'],
 ex:'helfen takes the Dativ → dem Kollegen.',tr:'I am helping the colleague.',say:'Ich helfe dem Kollegen.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich danke ___ für die Hilfe.',a:'dir',o:['dich','du','dein'],
 ex:'danken is a Dativ verb → dir, never dich.',tr:'I thank you for your help.',say:'Ich danke dir für die Hilfe.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Das Buch gehört ___ .',a:'mir',o:['mich','ich','meiner'],
 ex:'gehören takes the Dativ → mir.',tr:'The book belongs to me.',say:'Das Buch gehört mir.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Der Film hat ___ gut gefallen.',a:'mir',o:['mich','ich','meinen'],
 ex:'gefallen takes the Dativ: the film pleases me → mir.',tr:'I liked the film.',say:'Der Film hat mir gut gefallen.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich frage ___ Lehrer.',a:'den',o:['dem','der','des'],
 ex:'fragen is one of the verbs that take the Akkusativ — not the Dativ.',tr:'I am asking the teacher.',say:'Ich frage den Lehrer.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich gebe ___ Kind den Ball.',a:'dem',o:['das','den','des'],
 ex:'Verbs of giving take the person in the Dativ and the thing in the Akkusativ.',tr:'I give the child the ball.',say:'Ich gebe dem Kind den Ball.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich gebe ___ dem Kind.',a:'ihn',o:['ihm','er','den'],
 ex:'When one object is a pronoun it comes first: Ich gebe ihn dem Kind.',tr:'I am giving it to the child.',say:'Ich gebe ihn dem Kind.'},
{gid:'verbkasus',lv:3,sk:'Cases',s:'Ich vertraue ___ Freunden.',a:'meinen',o:['meine','meiner','meines'],
 ex:'vertrauen takes the Dativ; plural → meinen Freunden, with -n on the noun too.',tr:'I trust my friends.',say:'Ich vertraue meinen Freunden.'},

/* ---- ordinalzahlen ---- */
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Heute ist der ___ Oktober. (20.)',a:'zwanzigste',o:['zwanzigte','zwanzig','zwanzigsten'],
 ex:'From 20 on the ordinal is number + -ste → der zwanzigste.',tr:'Today is 20 October.',say:'Heute ist der zwanzigste Oktober.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Mein Geburtstag ist am ___ April. (7.)',a:'siebten',o:['siebte','siebenten','siebter'],
 ex:'7. is irregular (siebte) and after am it takes -n: am siebten.',tr:'My birthday is on 7 April.',say:'Mein Geburtstag ist am siebten April.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Ich wohne im ___ Stock. (3.)',a:'dritten',o:['dreiten','drittem','dritte'],
 ex:'3. is irregular dritte, and after im (Dativ) it becomes dritten.',tr:'I live on the third floor.',say:'Ich wohne im dritten Stock.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Er ist am ___ August geboren. (1.)',a:'ersten',o:['einten','eins','erste'],
 ex:'1. is erste; after am it takes -n → am ersten August.',tr:'He was born on 1 August.',say:'Er ist am ersten August geboren.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Das ist mein ___ Versuch. (2.)',a:'zweiter',o:['zweite','zweiten','zweites'],
 ex:'After a possessive the masculine Nominative takes -er: mein zweiter Versuch.',tr:'That is my second attempt.',say:'Das ist mein zweiter Versuch.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Zum ___ Mal, bitte! (2.)',a:'zweiten',o:['zweite','zweiter','zweites'],
 ex:'zu + dem = zum → Dativ, so the ordinal takes -en: zum zweiten Mal.',tr:'For the second time, please!',say:'Zum zweiten Mal, bitte!'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Das Datum „3. Mai 2026“ schreibt man in Zahlen ___ .',a:'3.5.2026',o:['5.3.2026','2026.5.3','3/5/26'],
 ex:'German dates always put the day first: 3.5.2026.',tr:'The date „3 May 2026“ is written 3.5.2026.',say:'Das Datum schreibt man 3.5.2026.'},
{gid:'ordinalzahlen',lv:3,sk:'Numbers',s:'Heute ist der ___ August. (8.)',a:'achte',o:['achtte','achtste','achten'],
 ex:'8. is irregular achte (one t only), and „der …“ is Nominative → achte.',tr:'Today is 8 August.',say:'Heute ist der achte August.'},

/* ---- relativsatz ---- */
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Der Mann, ___ dort steht, ist mein Lehrer.',a:'der',o:['den','dem','dessen'],
 ex:'Inside the clause the pronoun is the subject → Nominativ der.',tr:'The man who is standing there is my teacher.',say:'Der Mann, der dort steht, ist mein Lehrer.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Der Mann, ___ ich gestern traf, ist Arzt.',a:'den',o:['der','dem','dessen'],
 ex:'Inside the clause it is the direct object → Akkusativ den.',tr:'The man whom I met yesterday is a doctor.',say:'Der Mann, den ich gestern traf, ist Arzt.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Der Mann, ___ ich geholfen habe, wohnt hier.',a:'dem',o:['den','der','dessen'],
 ex:'helfen takes the Dativ, so the pronoun is dem.',tr:'The man I helped lives here.',say:'Der Mann, dem ich geholfen habe, wohnt hier.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Das Buch, ___ ich gelesen habe, war spannend.',a:'das',o:['dem','dessen','der'],
 ex:'das Buch is neuter and the object of lesen → neuter Akkusativ das.',tr:'The book I read was exciting.',say:'Das Buch, das ich gelesen habe, war spannend.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Die Leute, ___ ich vertraue, sind wenige.',a:'denen',o:['die','den','deren'],
 ex:'vertrauen takes the Dativ, and the Dativ plural pronoun is denen.',tr:'The people I trust are few.',say:'Die Leute, denen ich vertraue, sind wenige.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Der Mann, ___ Auto neu ist, heißt Weber.',a:'dessen',o:['dem','den','deren'],
 ex:'A possessive link needs the Genitiv: masculine dessen.',tr:'The man whose car is new is called Weber.',say:'Der Mann, dessen Auto neu ist, heißt Weber.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Der Stift, ___ ich schreibe, ist weg.',a:'mit dem',o:['mit den','womit ich','den mit'],
 ex:'The preposition stands before the pronoun and sets the case: mit + Dativ → mit dem.',tr:'The pen I write with is gone.',say:'Der Stift, mit dem ich schreibe, ist weg.'},
{gid:'relativsatz',lv:4,sk:'Clauses',s:'Die Stadt, ___ ich wohne, ist klein.',a:'in der',o:['in die','in dem','wo in'],
 ex:'in + wo? → Dativ, feminine die Stadt → in der. German never strands the preposition.',tr:'The city I live in is small.',say:'Die Stadt, in der ich wohne, ist klein.'},

/* ---- infinitivzu ---- */
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Ich habe keine Zeit, ins Kino ___ gehen.',a:'zu',o:['um','für','zum'],
 ex:'After an expression like „keine Zeit haben“ the infinitive needs a plain zu.',tr:'I have no time to go to the cinema.',say:'Ich habe keine Zeit, ins Kino zu gehen.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Es ist wichtig, pünktlich ___ sein.',a:'zu',o:['um','für','dass'],
 ex:'„Es ist wichtig“ is followed by an infinitive with zu.',tr:'It is important to be punctual.',say:'Es ist wichtig, pünktlich zu sein.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Ich fahre in die Stadt, ___ einzukaufen.',a:'um',o:['zu','für','damit'],
 ex:'Purpose with the same subject → um … zu.',tr:'I am going into town to do some shopping.',say:'Ich fahre in die Stadt, um einzukaufen.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Sie ging weg, ___ sich zu verabschieden.',a:'ohne',o:['um','anstatt','damit'],
 ex:'ohne … zu = without doing something.',tr:'She left without saying goodbye.',say:'Sie ging weg, ohne sich zu verabschieden.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Ich vergaß, dich ___ . (anrufen)',a:'anzurufen',o:['zu anrufen','anrufen zu','zu anzurufen'],
 ex:'With separable verbs the zu goes inside the word: anzurufen.',tr:'I forgot to call you.',say:'Ich vergaß, dich anzurufen.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Ich erkläre es, ___ du es verstehst.',a:'damit',o:['um','ohne','anstatt'],
 ex:'The subject changes (I explain, you understand), so you need damit, not um … zu.',tr:'I am explaining it so that you understand it.',say:'Ich erkläre es, damit du es verstehst.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Ich muss jetzt ___ .',a:'gehen',o:['zu gehen','um zu gehen','gegangen'],
 ex:'After a modal there is never a zu: Ich muss gehen.',tr:'I have to go now.',say:'Ich muss jetzt gehen.'},
{gid:'infinitivzu',lv:4,sk:'Clauses',s:'Er behauptet, alles verstanden ___ haben.',a:'zu',o:['um','ohne','und'],
 ex:'The past infinitive is Partizip II + zu haben: verstanden zu haben.',tr:'He claims to have understood everything.',say:'Er behauptet, alles verstanden zu haben.'},

/* ---- ndeklination ---- */
{gid:'ndeklination',lv:4,sk:'Cases',s:'Ich kenne diesen ___ gut. (der Student)',a:'Studenten',o:['Student','Studente','Students'],
 ex:'Student is an n-noun: every case but the Nominativ singular adds -en.',tr:'I know this student well.',say:'Ich kenne diesen Studenten gut.'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Ich habe mit meinem ___ gesprochen. (der Nachbar)',a:'Nachbarn',o:['Nachbar','Nachbaren','Nachbars'],
 ex:'Nachbar belongs to the n-declension → Dativ dem Nachbarn.',tr:'I spoke with my neighbour.',say:'Ich habe mit meinem Nachbarn gesprochen.'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Wie ist der Name des ___ ? (der Kunde)',a:'Kunden',o:['Kunde','Kundes','Kundens'],
 ex:'Masculine nouns in -e for people are n-nouns: des Kunden, not „des Kundes“.',tr:'What is the customer’s name?',say:'Wie ist der Name des Kunden?'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Das ist ein Problem für jeden ___ . (der Mensch)',a:'Menschen',o:['Mensch','Menschs','Mensche'],
 ex:'Mensch is one of the n-noun oddities → Akkusativ jeden Menschen.',tr:'That is a problem for every human being.',say:'Das ist ein Problem für jeden Menschen.'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Guten Tag, ___ Weber! (der Herr)',a:'Herr',o:['Herrn','Herren','Herrs'],
 ex:'Direct address is Nominativ, and there the word stays Herr.',tr:'Good day, Mr Weber!',say:'Guten Tag, Herr Weber!'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Ich habe ___ Weber gesehen. (der Herr)',a:'Herrn',o:['Herr','Herren','Herres'],
 ex:'Akkusativ → Herrn, with only -n: Herr takes -n, never -en.',tr:'I saw Mr Weber.',say:'Ich habe Herrn Weber gesehen.'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Ich sehe den ___ . (der Tisch)',a:'Tisch',o:['Tischen','Tische','Tisches'],
 ex:'Ordinary masculines are not n-nouns: den Tisch, never „den Tischen“.',tr:'I see the table.',say:'Ich sehe den Tisch.'},
{gid:'ndeklination',lv:4,sk:'Cases',s:'Die Bedeutung des ___ ist unklar. (der Name)',a:'Namens',o:['Namen','Name','Names'],
 ex:'Name is special: it adds -ns in the Genitiv → des Namens.',tr:'The meaning of the name is unclear.',say:'Die Bedeutung des Namens ist unklar.'},

/* ---- dawo ---- */
{gid:'dawo',lv:4,sk:'Prepositions',s:'Wartest du auf den Bus? — Ja, ich warte ___ .',a:'darauf',o:['auf ihn','darüber','danach'],
 ex:'warten auf + a thing fuses into darauf (with -r- because auf starts with a vowel).',tr:'Are you waiting for the bus? — Yes, I am waiting for it.',say:'Ja, ich warte darauf.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'Ich denke oft ___ . (an meine Kindheit)',a:'daran',o:['darauf','an sie','danach'],
 ex:'denken an + a thing → daran.',tr:'I often think about it.',say:'Ich denke oft daran.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'___ habt ihr gesprochen? (über das Thema)',a:'Worüber',o:['Über was','Wovon','Woran'],
 ex:'sprechen über + a thing → the question word worüber, with the -r- inserted.',tr:'What did you talk about?',say:'Worüber habt ihr gesprochen?'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'Das hängt ___ ab, ob es regnet.',a:'davon',o:['darauf','daran','dazu'],
 ex:'abhängen von → davon; von starts with a consonant, so there is no -r-.',tr:'That depends on whether it rains.',say:'Das hängt davon ab, ob es regnet.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'Ich kümmere mich ___ .',a:'darum',o:['dafür','davon','daran'],
 ex:'sich kümmern um → darum.',tr:'I will take care of it.',say:'Ich kümmere mich darum.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'Wartest du auf Anna? — Ja, ich warte ___ .',a:'auf sie',o:['darauf','worauf','auf ihr'],
 ex:'For a person you keep the preposition plus a pronoun: auf sie.',tr:'Are you waiting for Anna? — Yes, I am waiting for her.',say:'Ja, ich warte auf sie.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'Ich warte ___ , dass du endlich anrufst.',a:'darauf',o:['davon','darüber','daran'],
 ex:'warten auf → darauf, and a da-word can point forward to a dass-clause.',tr:'I am waiting for you to finally call.',say:'Ich warte darauf, dass du endlich anrufst.'},
{gid:'dawo',lv:4,sk:'Prepositions',s:'___ wartest du? (auf Anna)',a:'Auf wen',o:['Worauf','Wofür','Auf wem'],
 ex:'For a person the question is preposition + wen/wem: warten auf + Akkusativ → Auf wen.',tr:'Who are you waiting for?',say:'Auf wen wartest du?'},

/* ---- futur ---- */
{gid:'futur',lv:4,sk:'Verbs',s:'Morgen ___ ich nach Wien. (fliegen, fester Plan)',a:'fliege',o:['werde fliegen','bin geflogen','fliegen werde'],
 ex:'A fixed plan simply uses the present tense: Morgen fliege ich nach Wien.',tr:'Tomorrow I am flying to Vienna.',say:'Morgen fliege ich nach Wien.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Es ___ morgen regnen. (Vorhersage)',a:'wird',o:['ist','hat','werde'],
 ex:'A prediction takes Futur I: werden + Infinitiv.',tr:'It will rain tomorrow.',say:'Es wird morgen regnen.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Ich ___ dich nicht vergessen. (Versprechen)',a:'werde',o:['wird','will','bin'],
 ex:'A promise takes Futur I: ich werde … vergessen.',tr:'I will not forget you.',say:'Ich werde dich nicht vergessen.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Bis Freitag ___ wir umgezogen sein.',a:'werden',o:['sind','haben','wird'],
 ex:'Futur II for a deadline: werden + Partizip II + sein.',tr:'By Friday we will have moved house.',say:'Bis Freitag werden wir umgezogen sein.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Sie wird den Zug verpasst ___ . (Vermutung über die Vergangenheit)',a:'haben',o:['sein','werden','worden'],
 ex:'Futur II uses haben or sein — verpassen takes haben.',tr:'She will have missed the train.',say:'Sie wird den Zug verpasst haben.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Er ___ wohl krank sein. (Vermutung über jetzt)',a:'wird',o:['ist','hat','werde'],
 ex:'werden + wohl expresses an assumption about the present.',tr:'He is probably ill.',say:'Er wird wohl krank sein.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Nächste Woche ___ der Kurs an. (anfangen, Termin)',a:'fängt',o:['wird anfangen','anfängt','fängt werden'],
 ex:'A timetabled event takes the present tense, and the prefix an closes the sentence.',tr:'The course starts next week.',say:'Nächste Woche fängt der Kurs an.'},
{gid:'futur',lv:4,sk:'Verbs',s:'Ich ___ es dir morgen sagen. (Versprechen)',a:'werde',o:['wird','bin','habe'],
 ex:'Futur I: werde in position 2 and the infinitive sagen at the very end.',tr:'I will tell you tomorrow.',say:'Ich werde es dir morgen sagen.'},

/* ---- konnektoren ---- */
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Ich habe keine Zeit, ___ komme ich nicht.',a:'deshalb',o:['weil','denn','obwohl'],
 ex:'deshalb is an adverb in position 1, so the verb follows it directly.',tr:'I have no time, therefore I am not coming.',say:'Ich habe keine Zeit, deshalb komme ich nicht.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Es war spät, trotzdem ___ wir weiter.',a:'arbeiteten',o:['wir arbeiteten','zu arbeiten','arbeiten'],
 ex:'trotzdem fills position 1, so the conjugated verb must come straight after it.',tr:'It was late, nevertheless we kept working.',say:'Es war spät, trotzdem arbeiteten wir weiter.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Ich komme nicht, ___ ich keine Zeit habe.',a:'weil',o:['denn','deshalb','trotzdem'],
 ex:'The verb stands at the end, so the connector has to be subordinating: weil.',tr:'I am not coming because I have no time.',say:'Ich komme nicht, weil ich keine Zeit habe.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Ich komme nicht, ___ ich habe keine Zeit.',a:'denn',o:['weil','obwohl','damit'],
 ex:'The clause keeps normal word order (ich habe), so it needs denn — position 0.',tr:'I am not coming, for I have no time.',say:'Ich komme nicht, denn ich habe keine Zeit.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'___ ich müde war, bin ich mitgekommen.',a:'Obwohl',o:['Trotzdem','Aber','Denn'],
 ex:'obwohl is subordinating → war goes last, and the main verb follows the comma.',tr:'Although I was tired I came along.',say:'Obwohl ich müde war, bin ich mitgekommen.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Es regnete, ___ blieben wir zu Hause.',a:'deshalb',o:['weil','denn','dass'],
 ex:'The verb comes immediately after the connector, which marks it as the adverb deshalb.',tr:'It was raining, therefore we stayed at home.',say:'Es regnete, deshalb blieben wir zu Hause.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Weil es regnet, ___ ich zu Hause.',a:'bleibe',o:['ich bleibe','bleiben','zu bleiben'],
 ex:'The whole weil-clause is position 1, so the main verb comes straight after the comma.',tr:'Because it is raining I am staying at home.',say:'Weil es regnet, bleibe ich zu Hause.'},
{gid:'konnektoren',lv:4,sk:'Connectors',s:'Ich lerne viel, ___ ich die Prüfung bestehen will.',a:'weil',o:['denn','deshalb','trotzdem'],
 ex:'will sits at the very end, so only the subordinating weil fits.',tr:'I study a lot because I want to pass the exam.',say:'Ich lerne viel, weil ich die Prüfung bestehen will.'},

/* ---- nebensatzfragen ---- */
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Weißt du, wann ___ ?',a:'der Zug kommt',o:['kommt der Zug','der Zug zu kommen','kommt er der Zug'],
 ex:'An indirect question is a subordinate clause → the verb goes last.',tr:'Do you know when the train comes?',say:'Weißt du, wann der Zug kommt?'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Ich weiß nicht, wo ___ .',a:'sie wohnt',o:['wohnt sie','sie wohnen','wohnt sie denn'],
 ex:'The W-word stays as the connector and the verb moves to the end.',tr:'I do not know where she lives.',say:'Ich weiß nicht, wo sie wohnt.'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Ich frage mich, ___ er heute kommt.',a:'ob',o:['wenn','dass','wann'],
 ex:'A yes/no question becomes ob — „whether“ is always ob.',tr:'I wonder whether he is coming today.',say:'Ich frage mich, ob er heute kommt.'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Können Sie mir sagen, ___ Sie Zeit haben?',a:'ob',o:['wenn','dass','was'],
 ex:'„Do you have time?“ has no W-word, so the indirect version takes ob.',tr:'Could you tell me whether you have time?',say:'Können Sie mir sagen, ob Sie Zeit haben?'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Ich verstehe nicht, warum er sauer ___ .',a:'ist',o:['ist er','sein','zu sein'],
 ex:'Verb last in the indirect question: … warum er sauer ist.',tr:'I do not understand why he is annoyed.',say:'Ich verstehe nicht, warum er sauer ist.'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Könnten Sie mir sagen, wo der Bahnhof ___ ?',a:'ist',o:['ist er','sein','liegt der'],
 ex:'Even the politest question keeps the verb at the end of the clause.',tr:'Could you tell me where the station is?',say:'Könnten Sie mir sagen, wo der Bahnhof ist?'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'Höflicher als „Wo ist die Toilette?“: „Könnten Sie mir sagen, ___ die Toilette ist?“',a:'wo',o:['ob','dass','wohin'],
 ex:'A W-question keeps its W-word when it is embedded: … sagen, wo die Toilette ist.',tr:'More politely: „Could you tell me where the toilet is?“',say:'Könnten Sie mir sagen, wo die Toilette ist?'},
{gid:'nebensatzfragen',lv:4,sk:'Clauses',s:'___ er kommt, essen wir. (Bedingung)',a:'Wenn',o:['Ob','Dass','Wann'],
 ex:'A condition takes wenn; ob only ever means „whether“.',tr:'When he comes we will eat.',say:'Wenn er kommt, essen wir.'},

/* ---- konjunktiv1 ---- */
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Er sagte, er ___ krank. (sein)',a:'sei',o:['ist','wäre','war'],
 ex:'Reported speech takes Konjunktiv I; sein is irregular: er sei.',tr:'He said he was ill.',say:'Er sagte, er sei krank.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Sie sagte, sie ___ morgen Zeit. (haben)',a:'habe',o:['hat','hätte','hatte'],
 ex:'3rd person singular Konjunktiv I = stem + -e → er/sie habe.',tr:'She said she had time tomorrow.',say:'Sie sagte, sie habe morgen Zeit.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Der Minister erklärte, die Lage ___ ernst.',a:'sei',o:['ist','war','wird'],
 ex:'Newspaper German reports with Konjunktiv I: die Lage sei ernst.',tr:'The minister declared the situation was serious.',say:'Der Minister erklärte, die Lage sei ernst.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Er versprach, er ___ sich darum kümmern.',a:'werde',o:['wird','würde','wurde'],
 ex:'A reported future uses werde + Infinitiv.',tr:'He promised he would see to it.',say:'Er versprach, er werde sich darum kümmern.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Sie behauptete, sie ___ nichts davon gewusst.',a:'habe',o:['hat','hätte','hatte'],
 ex:'Any past collapses into the Konjunktiv I perfect: habe … gewusst.',tr:'She claimed she had known nothing about it.',say:'Sie behauptete, sie habe nichts davon gewusst.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Sie sagten, sie ___ keine Zeit. (Plural)',a:'hätten',o:['haben','habe','hatten'],
 ex:'In the plural Konjunktiv I looks like the indicative, so German switches to Konjunktiv II: hätten.',tr:'They said they had no time.',say:'Sie sagten, sie hätten keine Zeit.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'Er sagte, er ___ mich nicht. (kennen)',a:'kenne',o:['kennt','kennte','kannte'],
 ex:'Konjunktiv I keeps the infinitive stem and adds -e: er kenne — no vowel change.',tr:'He said he did not know me.',say:'Er sagte, er kenne mich nicht.'},
{gid:'konjunktiv1',lv:5,sk:'Konjunktiv',s:'In der Zeitung steht: „Laut Polizei ___ niemand verletzt worden.“',a:'sei',o:['ist','wäre','war'],
 ex:'A reported passive in the press: sei + Partizip II + worden.',tr:'The paper writes: „According to the police nobody was injured.“',say:'Laut Polizei sei niemand verletzt worden.'},

/* ---- passiversatz ---- */
{gid:'passiversatz',lv:5,sk:'Passive',s:'Der Laden ___ seit Montag geschlossen. (Zustand)',a:'ist',o:['wird','wurde','werden'],
 ex:'A lasting state takes the Zustandspassiv with sein.',tr:'The shop has been closed since Monday.',say:'Der Laden ist seit Montag geschlossen.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'Die Tür ___ gerade geöffnet. (Vorgang)',a:'wird',o:['ist','war','worden'],
 ex:'„gerade“ shows that somebody is acting right now → Vorgangspassiv with werden.',tr:'The door is being opened right now.',say:'Die Tür wird gerade geöffnet.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'Der Fehler ___ sich leicht beheben.',a:'lässt',o:['ist','wird','kann'],
 ex:'sich lassen + Infinitiv expresses possibility: lässt sich leicht beheben.',tr:'The error can easily be fixed.',say:'Der Fehler lässt sich leicht beheben.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'Das Formular ist bis Freitag ___ . (einreichen)',a:'einzureichen',o:['eingereicht','einreichen','zu einreichen'],
 ex:'sein + zu + Infinitiv expresses obligation; in a separable verb zu goes inside.',tr:'The form is to be submitted by Friday.',say:'Das Formular ist bis Freitag einzureichen.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'Diese Software ist nicht mehr ___ . (warten)',a:'wartbar',o:['gewartet','wartlich','zu warten sein'],
 ex:'-bar builds a compact passive adjective: wartbar = can be maintained.',tr:'This software can no longer be maintained.',say:'Diese Software ist nicht mehr wartbar.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'___ repariert das leicht. (allgemein, gesprochen)',a:'Man',o:['Es','Sich','Einer'],
 ex:'man is the everyday substitute for a passive: Man repariert das leicht.',tr:'That is easily repaired.',say:'Man repariert das leicht.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'___ wird geholfen. (der Kunde)',a:'Dem Kunden',o:['Der Kunde','Den Kunden','Des Kunden'],
 ex:'Dativ verbs keep their Dativ in the passive and get no subject: Dem Kunden wird geholfen.',tr:'The customer is being helped.',say:'Dem Kunden wird geholfen.'},
{gid:'passiversatz',lv:5,sk:'Passive',s:'Die Stadt wurde ___ das Hochwasser zerstört.',a:'durch',o:['von','vom','mit'],
 ex:'A cause or means takes durch + Akkusativ; von is reserved for a person or active force.',tr:'The city was destroyed by the flood.',say:'Die Stadt wurde durch das Hochwasser zerstört.'},

/* ---- partizipattribut ---- */
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'das ___ Kind (schlafen, gerade)',a:'schlafende',o:['geschlafene','schlafen','schlafend'],
 ex:'Partizip I = Infinitiv + d, plus the adjective ending: das schlafende Kind.',tr:'the sleeping child',say:'das schlafende Kind'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'das ___ Ei (kochen, schon fertig)',a:'gekochte',o:['kochende','kochen','gekocht'],
 ex:'Finished and passive → Partizip II with an ending: das gekochte Ei.',tr:'the boiled egg',say:'das gekochte Ei'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'das ___ Fenster (reparieren, schon erledigt)',a:'reparierte',o:['reparierende','zu reparierende','reparieren'],
 ex:'Partizip II means the work is done; „zu reparierende“ would mean it still needs repairing.',tr:'the repaired window',say:'das reparierte Fenster'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'die ___ Preise (steigen)',a:'steigenden',o:['gestiegenen','steigend','steigen'],
 ex:'Active and ongoing → Partizip I with the plural ending: die steigenden Preise.',tr:'the rising prices',say:'die steigenden Preise'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'der ___ Hund (bellen)',a:'bellende',o:['gebellte','bellend','bellen'],
 ex:'The dog is doing the barking → Partizip I: der bellende Hund.',tr:'the barking dog',say:'der bellende Hund'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'die noch ___ Frage (klären, muss noch geschehen)',a:'zu klärende',o:['geklärte','klärende','zu klären'],
 ex:'zu + Partizip I expresses necessity: the question that still has to be clarified.',tr:'the question still to be clarified',say:'die noch zu klärende Frage'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'der vom Chef ___ Vertrag (unterschreiben)',a:'unterschriebene',o:['unterschreibende','unterschrieben','zu unterschreibende'],
 ex:'Passive and completed → Partizip II with the ending: der unterschriebene Vertrag.',tr:'the contract signed by the boss',say:'der vom Chef unterschriebene Vertrag'},
{gid:'partizipattribut',lv:5,sk:'Adjectives',s:'die gestern ___ Gäste (ankommen)',a:'angekommenen',o:['ankommenden','angekommen','anzukommenden'],
 ex:'With sein-verbs the Partizip II is active and finished: die angekommenen Gäste.',tr:'the guests who arrived yesterday',say:'die gestern angekommenen Gäste'},

/* ---- subjektivmodal ---- */
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Er sieht furchtbar aus. Er ___ krank sein. (fast sicher)',a:'muss',o:['soll','will','darf'],
 ex:'muss + Infinitiv is a conclusion of about 95 % certainty.',tr:'He looks awful. He must be ill.',say:'Er muss krank sein.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Die Zeitung schreibt: Der Politiker ___ Konten im Ausland haben.',a:'soll',o:['muss','will','darf'],
 ex:'soll marks hearsay — „is said to“; the paper is not vouching for it.',tr:'The paper writes the politician is said to have accounts abroad.',say:'Der Politiker soll Konten im Ausland haben.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Sie ___ Ärztin sein — das behauptet sie selbst.',a:'will',o:['soll','muss','darf'],
 ex:'will marks a self-claim: she says so herself.',tr:'She claims to be a doctor.',say:'Sie will Ärztin sein.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Der Film ___ etwa zwei Stunden dauern. (höfliche Schätzung)',a:'dürfte',o:['darf','muss','will'],
 ex:'dürfte is a polite estimate of about 75 % certainty.',tr:'The film is probably about two hours long.',say:'Der Film dürfte etwa zwei Stunden dauern.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Das ___ stimmen, beweist aber nichts.',a:'mag',o:['muss','soll','will'],
 ex:'mag concedes a possibility: „that may be true, but …“.',tr:'That may be true, but it proves nothing.',say:'Das mag stimmen, beweist aber nichts.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Das ___ stimmen — ich bin mir aber nicht sicher.',a:'könnte',o:['muss','soll','will'],
 ex:'könnte marks a mere possibility, roughly 40 % certainty.',tr:'That could be right — but I am not sure.',say:'Das könnte stimmen.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Das Paket muss unterwegs verloren gegangen ___ .',a:'sein',o:['haben','werden','worden'],
 ex:'The past of a subjective modal is Partizip II + haben/sein; gehen takes sein.',tr:'The parcel must have got lost in transit.',say:'Das Paket muss unterwegs verloren gegangen sein.'},
{gid:'subjektivmodal',lv:5,sk:'Verbs',s:'Er ___ nichts davon gewusst haben. (er behauptet es selbst)',a:'will',o:['soll','muss','dürfte'],
 ex:'will + Perfekt-Infinitiv = he claims to have …',tr:'He claims to have known nothing about it.',say:'Er will nichts davon gewusst haben.'},

/* ---- nominalstil ---- */
{gid:'nominalstil',lv:5,sk:'Style',s:'weil er krank war → ___ seiner Krankheit',a:'wegen',o:['trotz','während','durch'],
 ex:'A cause becomes wegen + Genitiv: wegen seiner Krankheit.',tr:'because he was ill → because of his illness',say:'wegen seiner Krankheit'},
{gid:'nominalstil',lv:5,sk:'Style',s:'obwohl es regnete → ___ des Regens',a:'trotz',o:['wegen','während','nach'],
 ex:'A concession becomes trotz + Genitiv: trotz des Regens.',tr:'although it was raining → despite the rain',say:'trotz des Regens'},
{gid:'nominalstil',lv:5,sk:'Style',s:'nachdem er angekommen war → ___ seiner Ankunft',a:'nach',o:['vor','bei','während'],
 ex:'„after“ becomes nach + Dativ: nach seiner Ankunft.',tr:'after he had arrived → after his arrival',say:'nach seiner Ankunft'},
{gid:'nominalstil',lv:5,sk:'Style',s:'bevor er abreiste → ___ seiner Abreise',a:'vor',o:['nach','bei','seit'],
 ex:'„before“ becomes vor + Dativ: vor seiner Abreise.',tr:'before he departed → before his departure',say:'vor seiner Abreise'},
{gid:'nominalstil',lv:5,sk:'Style',s:'während sie studierte → während ___ Studiums',a:'ihres',o:['ihrem','ihr','ihre'],
 ex:'während takes the Genitiv: während ihres Studiums.',tr:'while she was studying → during her studies',say:'während ihres Studiums'},
{gid:'nominalstil',lv:5,sk:'Style',s:'indem man übt → ___ Üben',a:'durch',o:['bei','mit','für'],
 ex:'A means becomes durch + an infinitive used as a noun: durch Üben.',tr:'by practising → through practice',say:'durch Üben'},
{gid:'nominalstil',lv:5,sk:'Style',s:'Nachdem wir die Daten geprüft hatten, … → ___ der Daten …',a:'Nach Prüfung',o:['Nach prüfen','Nach der Prüfen','Bei Prüfung die'],
 ex:'prüfen → die Prüfung; nach + Dativ, and the object turns into a Genitiv: Nach Prüfung der Daten.',tr:'After we had checked the data … → After checking the data …',say:'Nach Prüfung der Daten melden wir uns.'},
{gid:'nominalstil',lv:5,sk:'Style',s:'damit die Qualität steigt → ___ Steigerung der Qualität',a:'zur',o:['für','zum','durch'],
 ex:'Purpose becomes zu + Dativ; die Steigerung is feminine → zur Steigerung.',tr:'so that quality rises → in order to raise quality',say:'zur Steigerung der Qualität'},

/* ---- genitivprep ---- */
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Wegen ___ Streiks fahren keine Züge.',a:'des',o:['dem','der','den'],
 ex:'wegen + Genitiv, masculine der Streik → wegen des Streiks.',tr:'Because of the strike no trains are running.',say:'Wegen des Streiks fahren keine Züge.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Trotz ___ Kritik hält er daran fest.',a:'der',o:['die','dem','des'],
 ex:'die Kritik is feminine → Genitiv der Kritik.',tr:'Despite the criticism he stands by it.',say:'Trotz der Kritik hält er daran fest.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Während ___ Prüfung ist Sprechen verboten.',a:'der',o:['die','dem','des'],
 ex:'während + Genitiv; die Prüfung is feminine → der Prüfung.',tr:'Talking is forbidden during the exam.',say:'Während der Prüfung ist Sprechen verboten.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Innerhalb ___ Monats müssen Sie widersprechen.',a:'eines',o:['einem','einen','ein'],
 ex:'innerhalb + Genitiv; der Monat is masculine → eines Monats.',tr:'You must object within a month.',say:'Innerhalb eines Monats müssen Sie widersprechen.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'___ des schlechten Wetters wurde das Konzert verschoben.',a:'Aufgrund',o:['Wegen dem','Trotz dem','Während den'],
 ex:'Aufgrund + Genitiv fits both the cause and the case; the others use the Dativ.',tr:'Because of the bad weather the concert was postponed.',say:'Aufgrund des schlechten Wetters wurde das Konzert verschoben.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Hinsichtlich ___ Kosten bestehen noch Unklarheiten.',a:'der',o:['die','den','des'],
 ex:'die Kosten is plural → Genitiv plural der Kosten.',tr:'Regarding the costs uncertainty remains.',say:'Hinsichtlich der Kosten bestehen noch Unklarheiten.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Im Prüfungstext schreibt man: „___ Regens fiel das Spiel aus.“',a:'wegen des',o:['wegen dem','wegen den','wegen der'],
 ex:'Spoken „wegen dem Regen“ is still marked wrong; written German needs wegen des Regens.',tr:'In an exam text you write „because of the rain the match was cancelled“.',say:'Wegen des Regens fiel das Spiel aus.'},
{gid:'genitivprep',lv:5,sk:'Prepositions',s:'Infolge ___ Unfalls war die Straße gesperrt.',a:'des',o:['dem','den','der'],
 ex:'infolge + Genitiv; der Unfall is masculine → des Unfalls.',tr:'As a result of the accident the road was closed.',say:'Infolge des Unfalls war die Straße gesperrt.'},

/* ---- zweiteilig ---- */
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Er trinkt ___ Kaffee noch Tee.',a:'weder',o:['nicht','kein','entweder'],
 ex:'weder … noch = neither … nor, and it is already negative on its own.',tr:'He drinks neither coffee nor tea.',say:'Er trinkt weder Kaffee noch Tee.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'___ wir fahren heute, oder wir bleiben.',a:'Entweder',o:['Weder','Sowohl','Zwar'],
 ex:'entweder … oder = either … or.',tr:'Either we travel today or we stay.',say:'Entweder wir fahren heute, oder wir bleiben.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Sie spricht sowohl Russisch ___ Chinesisch.',a:'als auch',o:['als','wie auch','und auch'],
 ex:'The fixed pair is sowohl … als auch.',tr:'She speaks both Russian and Chinese.',say:'Sie spricht sowohl Russisch als auch Chinesisch.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Es ist nicht nur teuer, ___ auch schlecht.',a:'sondern',o:['aber','denn','oder'],
 ex:'The fixed pair is nicht nur … sondern auch.',tr:'It is not only expensive but also bad.',say:'Es ist nicht nur teuer, sondern auch schlecht.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Es ist ___ teuer, aber es lohnt sich.',a:'zwar',o:['sowohl','weder','entweder'],
 ex:'zwar … aber concedes a point and then counters it.',tr:'It is expensive, admittedly, but it is worth it.',say:'Es ist zwar teuer, aber es lohnt sich.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Je mehr man übt, ___ .',a:'desto leichter wird es',o:['desto es leichter wird','desto wird es leicht','umso es leichter wird'],
 ex:'The desto-half inverts: desto + comparative + verb + subject.',tr:'The more you practise, the easier it gets.',say:'Je mehr man übt, desto leichter wird es.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Je länger ich ___ , desto nervöser werde ich.',a:'warte',o:['warte ich','zu warten','warten'],
 ex:'The je-clause is subordinate → the verb goes last.',tr:'The longer I wait, the more nervous I get.',say:'Je länger ich warte, desto nervöser werde ich.'},
{gid:'zweiteilig',lv:5,sk:'Connectors',s:'Weder der Chef ___ die Kollegen wussten davon.',a:'noch',o:['oder','und','nicht'],
 ex:'weder is always answered by noch — and you never add nicht or kein.',tr:'Neither the boss nor the colleagues knew about it.',say:'Weder der Chef noch die Kollegen wussten davon.'},

/* ---- satzklammer ---- */
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Ordne: „Ich · muss · heute · früher · nach Hause · gehen“ → ___',a:'Ich muss heute früher nach Hause gehen.',o:['Ich muss nach Hause heute früher gehen.','Ich heute muss früher nach Hause gehen.','Ich muss gehen heute früher nach Hause.'],
 ex:'muss in position 2, gehen at the end, and inside: time → manner → place.',tr:'I have to go home earlier today.',say:'Ich muss heute früher nach Hause gehen.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Ich habe ___ gegeben. (ihm · das Buch)',a:'ihm das Buch',o:['das Buch ihm','ihn das Buch','dem Buch ihm'],
 ex:'Dativ before Akkusativ: ihm das Buch.',tr:'I gave him the book.',say:'Ich habe ihm das Buch gegeben.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Morgen ___ ich um sechs auf.',a:'stehe',o:['stehe auf','aufstehe','auf stehe'],
 ex:'The conjugated verb takes position 2 and the prefix auf closes the frame.',tr:'Tomorrow I get up at six.',say:'Morgen stehe ich um sechs auf.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Er ist nach Hause ___ .',a:'gegangen',o:['gegangen ist','gehen','ging'],
 ex:'The Partizip II closes the sentence frame at the very end.',tr:'He has gone home.',say:'Er ist nach Hause gegangen.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Ich will dir morgen alles ___ .',a:'erklären',o:['erkläre','erklärt','zu erklären'],
 ex:'The infinitive closes the frame opened by the modal in position 2.',tr:'I want to explain everything to you tomorrow.',say:'Ich will dir morgen alles erklären.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Ich fahre ___ mit dem Zug nach Berlin. (morgen · wegen der Prüfung)',a:'morgen wegen der Prüfung',o:['wegen der Prüfung morgen','mit dem Zug morgen','morgen nach Berlin'],
 ex:'TeKaMoLo: temporal (morgen) before kausal (wegen der Prüfung), then modal and local.',tr:'Tomorrow I am going to Berlin by train because of the exam.',say:'Ich fahre morgen wegen der Prüfung mit dem Zug nach Berlin.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'Ich habe ___ gesagt. (es · ihr)',a:'es ihr',o:['ihr es','sie ihr','es sie'],
 ex:'Among pronouns the order flips: Akkusativ (es) before Dativ (ihr).',tr:'I told her that.',say:'Ich habe es ihr gesagt.'},
{gid:'satzklammer',lv:5,sk:'Sentences',s:'___ fahre ich morgen mit dem Zug.',a:'Nach Berlin',o:['Morgen nach Berlin fahre','Ich nach Berlin','Fahre nach Berlin'],
 ex:'Any single element may fill position 1 for emphasis — the verb still stands second.',tr:'To Berlin I am travelling tomorrow by train.',say:'Nach Berlin fahre ich morgen mit dem Zug.'},

/* ---- erwpartizip ---- */
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'die seit Jahren ___ Mieten (steigen)',a:'steigenden',o:['gestiegenen','steigend','steigenen'],
 ex:'Partizip I = active and simultaneous: die Mieten, die seit Jahren steigen.',tr:'the rents that have been rising for years',say:'die seit Jahren steigenden Mieten'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'der gestern ___ Wagen (reparieren)',a:'reparierte',o:['reparierende','repariert','zu reparierende'],
 ex:'Partizip II = passive and completed: der Wagen, der gestern repariert wurde.',tr:'the car that was repaired yesterday',say:'der gestern reparierte Wagen'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'die in Berlin ___ Künstlerin (leben)',a:'lebende',o:['gelebte','lebend','gelebten'],
 ex:'She is living there now → Partizip I with the feminine ending: lebende.',tr:'the artist living in Berlin',say:'die in Berlin lebende Künstlerin'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'das vom Chef ___ Dokument (unterschreiben)',a:'unterschriebene',o:['unterschreibende','unterschrieben','zu unterschreibende'],
 ex:'„vom Chef“ marks a passive agent → Partizip II: unterschriebene.',tr:'the document signed by the boss',say:'das vom Chef unterschriebene Dokument'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'die noch ___ Frage (klären)',a:'zu klärende',o:['geklärte','klärende','zu klären'],
 ex:'zu + Partizip I expresses necessity: the question that still has to be clarified.',tr:'the question still to be clarified',say:'die noch zu klärende Frage'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'Entpacke: „der seit Monaten andauernde Streit“ → der Streit, der seit Monaten ___ .',a:'andauert',o:['angedauert wurde','andauern muss','andauernd ist'],
 ex:'Partizip I is active and ongoing → present tense in the relative clause: andauert.',tr:'the dispute that has been going on for months',say:'der Streit, der seit Monaten andauert'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'Entpacke: „die gestern beschlossenen Maßnahmen“ → die Maßnahmen, die gestern ___ .',a:'beschlossen wurden',o:['beschlossen haben','beschließen','beschlossen sind'],
 ex:'Partizip II of a haben-verb unpacks into a passive clause: die beschlossen wurden.',tr:'the measures that were decided yesterday',say:'die Maßnahmen, die gestern beschlossen wurden'},
{gid:'erwpartizip',lv:6,sk:'Clauses',s:'Entpacke: „das vor zwei Wochen erschienene Buch“ → das Buch, das vor zwei Wochen ___ .',a:'erschienen ist',o:['erschienen wurde','erscheint','erschienen hat'],
 ex:'erscheinen is a sein-verb, so its Partizip II stays active: das erschienen ist.',tr:'the book that came out two weeks ago',say:'das Buch, das vor zwei Wochen erschienen ist'},

/* ---- funktionsverben ---- */
{gid:'funktionsverben',lv:6,sk:'Style',s:'Ich möchte einen Antrag ___ .',a:'stellen',o:['machen','tun','geben'],
 ex:'The fixed pair is einen Antrag stellen; the single verb is beantragen.',tr:'I would like to file an application.',say:'Ich möchte einen Antrag stellen.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Der Vorstand hat eine schwierige Entscheidung ___ . (treffen)',a:'getroffen',o:['gemacht','genommen','gegeben'],
 ex:'eine Entscheidung treffen — never „machen“, however natural that feels in English.',tr:'The board made a difficult decision.',say:'Der Vorstand hat eine schwierige Entscheidung getroffen.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'An dieser Stelle möchte ich Kritik ___ .',a:'üben',o:['machen','geben','nehmen'],
 ex:'Kritik üben is the fixed pair; the single verb is kritisieren.',tr:'At this point I would like to voice criticism.',say:'An dieser Stelle möchte ich Kritik üben.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Diese Möglichkeit sollten wir in Betracht ___ .',a:'ziehen',o:['nehmen','machen','bringen'],
 ex:'in Betracht ziehen = erwägen, to take into consideration.',tr:'We should take this possibility into consideration.',say:'Diese Möglichkeit sollten wir in Betracht ziehen.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Die Unterlagen werden Ihnen zur Verfügung ___ .',a:'gestellt',o:['gemacht','gegeben','gebracht'],
 ex:'zur Verfügung stellen = bereitstellen; in the passive: werden zur Verfügung gestellt.',tr:'The documents will be made available to you.',say:'Die Unterlagen werden Ihnen zur Verfügung gestellt.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Wir müssen auf die Nachbarn Rücksicht ___ .',a:'nehmen',o:['machen','ziehen','üben'],
 ex:'Rücksicht nehmen auf = berücksichtigen, to show consideration for.',tr:'We have to show consideration for the neighbours.',say:'Wir müssen auf die Nachbarn Rücksicht nehmen.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Ich möchte das Thema zur Sprache ___ .',a:'bringen',o:['stellen','nehmen','machen'],
 ex:'zur Sprache bringen = ansprechen, to bring a topic up.',tr:'I would like to bring the topic up.',say:'Ich möchte das Thema zur Sprache bringen.'},
{gid:'funktionsverben',lv:6,sk:'Style',s:'Es wurden sofort Maßnahmen ___ . (ergreifen)',a:'ergriffen',o:['genommen','gemacht','gezogen'],
 ex:'Maßnahmen ergreifen is the pair, and it passivises easily: wurden Maßnahmen ergriffen.',tr:'Measures were taken immediately.',say:'Es wurden sofort Maßnahmen ergriffen.'},

/* ---- modalpartikeln ---- */
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Komm ___ mit! (freundliche Einladung)',a:'doch',o:['etwa','bloß','wohl'],
 ex:'Unstressed doch softens a command into an invitation.',tr:'Do come along!',say:'Komm doch mit!'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Sag ___ , wie heißt du? (ganz locker)',a:'mal',o:['doch','ja','etwa'],
 ex:'mal makes the question casual and low-stakes.',tr:'Say, what is your name?',say:'Sag mal, wie heißt du?'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Wo bist du ___ ? (freundliche Neugier)',a:'denn',o:['ja','eben','ruhig'],
 ex:'denn in a question adds friendly curiosity rather than pressure.',tr:'So where are you?',say:'Wo bist du denn?'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Das ist ___ klar! (das wissen wir beide)',a:'ja',o:['denn','mal','etwa'],
 ex:'ja signals „as we both know“ — shared knowledge.',tr:'That is obvious, of course!',say:'Das ist ja klar!'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'So ist das ___ . (Resignation)',a:'eben',o:['ja','denn','etwa'],
 ex:'eben (or halt) expresses resignation: that is just how it is.',tr:'That is just how it is.',say:'So ist das eben.'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Hast du das ___ vergessen? (Ungläubigkeit)',a:'etwa',o:['mal','ruhig','eben'],
 ex:'etwa in a question signals disbelief: „surely you haven’t forgotten?“',tr:'Surely you haven’t forgotten that?',say:'Hast du das etwa vergessen?'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Nimm ___ noch ein Stück! (Erlaubnis)',a:'ruhig',o:['etwa','bloß','denn'],
 ex:'ruhig means „feel free to“ — it gives permission.',tr:'Do feel free to take another piece!',say:'Nimm ruhig noch ein Stück!'},
{gid:'modalpartikeln',lv:6,sk:'Style',s:'Er ist ___ krank. (Vermutung)',a:'wohl',o:['ja','mal','ruhig'],
 ex:'wohl marks a guess: he is probably ill.',tr:'He is probably ill.',say:'Er ist wohl krank.'},

/* ---- adverbialsaetze ---- */
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'___ die Daten fehlen, lässt sich nichts beweisen. (bekannter Grund)',a:'Da',o:['Damit','Indem','Sodass'],
 ex:'da introduces a reason already known to the reader and likes the front position.',tr:'Since the data is missing, nothing can be proven.',say:'Da die Daten fehlen, lässt sich nichts beweisen.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Der Plan überzeugt nicht, ___ die Kosten unklar bleiben.',a:'zumal',o:['sodass','indem','sofern'],
 ex:'zumal adds a reinforcing reason: „especially since“.',tr:'The plan is not convincing, especially since the costs remain unclear.',say:'Der Plan überzeugt nicht, zumal die Kosten unklar bleiben.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Man kann viel erreichen, ___ man früh beginnt. (Mittel)',a:'indem',o:['damit','sodass','obgleich'],
 ex:'indem names the means: by starting early.',tr:'You can achieve a lot by starting early.',say:'Man kann viel erreichen, indem man früh beginnt.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Es regnete, ___ wir zu Hause blieben. (Folge)',a:'sodass',o:['damit','indem','sofern'],
 ex:'sodass marks a consequence; damit would mark an intention.',tr:'It was raining, so we stayed at home.',say:'Es regnete, sodass wir zu Hause blieben.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Die Löhne stagnierten, ___ die Mieten stiegen. (Gegensatz)',a:'wohingegen',o:['sodass','zumal','damit'],
 ex:'wohingegen is the adversative conjunction: whereas.',tr:'Wages stagnated, whereas rents rose.',say:'Die Löhne stagnierten, wohingegen die Mieten stiegen.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Konzessiv ist die Konjunktion ___ .',a:'wenngleich',o:['sodass','indem','sofern'],
 ex:'wenngleich = „even though“ → concession. sodass is result, indem means, sofern condition.',tr:'The concessive conjunction is wenngleich.',say:'Konzessiv ist die Konjunktion wenngleich.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Er tut so, als ob er alles ___ .',a:'wüsste',o:['weiß','wusste','gewusst hat'],
 ex:'als ob always takes the Konjunktiv II: wüsste.',tr:'He acts as if he knew everything.',say:'Er tut so, als ob er alles wüsste.'},
{gid:'adverbialsaetze',lv:6,sk:'Clauses',s:'Er reagierte, als ___ nichts geschehen.',a:'wäre',o:['ob wäre','war','hätte'],
 ex:'Drop the ob and the verb moves straight behind als: als wäre nichts geschehen.',tr:'He reacted as if nothing had happened.',say:'Er reagierte, als wäre nichts geschehen.'},

/* ---- register ---- */
{gid:'register',lv:6,sk:'Style',s:'Im Geschäftsbrief: „Ich habe Ihre Anfrage ___ .“',a:'erhalten',o:['gekriegt','rausgefunden','abgecheckt'],
 ex:'erhalten is the formal register for „receive“; kriegen is colloquial.',tr:'In a business letter: „I have received your enquiry.“',say:'Ich habe Ihre Anfrage erhalten.'},
{gid:'register',lv:6,sk:'Style',s:'Umgangssprachlich sagt man statt „bekommen“ oft ___ .',a:'kriegen',o:['erhalten','erwerben','ermitteln'],
 ex:'kriegen is the casual everyday word; erhalten is its formal counterpart.',tr:'Colloquially people often say kriegen instead of bekommen.',say:'Umgangssprachlich sagt man oft kriegen.'},
{gid:'register',lv:6,sk:'Style',s:'Formell für „anfangen“ schreibt man ___ .',a:'beginnen',o:['losgehen','anmachen','rangehen'],
 ex:'beginnen is the neutral-to-formal verb; losgehen is spoken German.',tr:'Formally you write beginnen instead of anfangen.',say:'Formell schreibt man beginnen.'},
{gid:'register',lv:6,sk:'Style',s:'Formell für „jetzt“ schreibt man ___ .',a:'derzeit',o:['grad','jetzt mal','irgendwann'],
 ex:'derzeit is the formal written equivalent of jetzt.',tr:'Formally you write derzeit instead of jetzt.',say:'Formell schreibt man derzeit.'},
{gid:'register',lv:6,sk:'Style',s:'Formell für „aber“ schreibt man ___ .',a:'jedoch',o:['aber halt','echt aber','bloß'],
 ex:'jedoch is the formal contrast connector.',tr:'Formally you write jedoch instead of aber.',say:'Formell schreibt man jedoch.'},
{gid:'register',lv:6,sk:'Style',s:'Formell für „fast“ schreibt man ___ .',a:'nahezu',o:['voll','echt','ziemlich knapp'],
 ex:'nahezu belongs to the formal register; voll and echt are casual intensifiers.',tr:'Formally you write nahezu instead of fast.',say:'Formell schreibt man nahezu.'},
{gid:'register',lv:6,sk:'Style',s:'In eine Bewerbung passt: ___',a:'Ich habe die Stelle erhalten.',o:['Ich hab den Job gekriegt.','Ich hab echt Bock auf den Job.','Den Job hab ich voll gern.'],
 ex:'A formal letter needs erhalten and full forms — no kriegen, no hab, no echt.',tr:'Suitable for an application: „I have received the position.“',say:'Ich habe die Stelle erhalten.'},
{gid:'register',lv:6,sk:'Style',s:'In einer Beschwerde: „___ der Verspätung bitte ich um Erstattung.“',a:'Aufgrund',o:['Wegen dem','Weil','Weil wegen'],
 ex:'Formal writing uses a Genitive preposition: Aufgrund der Verspätung.',tr:'In a complaint: „Because of the delay I request a refund.“',say:'Aufgrund der Verspätung bitte ich um Erstattung.'},

/* ---- idiomatik ---- */
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Mit dieser Analyse haben Sie den Nagel auf den ___ getroffen.',a:'Kopf',o:['Finger','Punkt','Tisch'],
 ex:'den Nagel auf den Kopf treffen = to hit the nail on the head. The image is fixed.',tr:'With this analysis you hit the nail on the head.',say:'Mit dieser Analyse haben Sie den Nagel auf den Kopf getroffen.'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Nach der Operation ist er über den ___ .',a:'Berg',o:['Hügel','Wald','Fluss'],
 ex:'über den Berg sein = to be out of the woods; positive in colour.',tr:'After the operation he is out of the woods.',say:'Nach der Operation ist er über den Berg.'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Ich habe die ___ voll! (es reicht mir)',a:'Nase',o:['Hand','Ohren','Augen'],
 ex:'die Nase voll haben = to be fed up — clearly negative, so use it with care.',tr:'I have had enough!',say:'Ich habe die Nase voll!'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Reden wir nicht um den heißen ___ herum.',a:'Brei',o:['Kaffee','Suppe','Topf'],
 ex:'um den heißen Brei herumreden = to beat around the bush.',tr:'Let us not beat around the bush.',say:'Reden wir nicht um den heißen Brei herum.'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Können wir das unter vier ___ besprechen?',a:'Augen',o:['Ohren','Händen','Wänden'],
 ex:'unter vier Augen = in private, just the two of us.',tr:'Can we discuss that in private?',say:'Können wir das unter vier Augen besprechen?'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Da bist du auf dem ___ . (du irrst dich)',a:'Holzweg',o:['Fettnäpfchen','Bahnhof','Stich'],
 ex:'auf dem Holzweg sein = to be on the wrong track.',tr:'You are on the wrong track there.',say:'Da bist du auf dem Holzweg.'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'Ich habe nur ___ verstanden. (gar nichts)',a:'Bahnhof',o:['Holzweg','Brei','Schwein'],
 ex:'nur Bahnhof verstehen = not to understand a word; informal and slightly funny.',tr:'I did not understand a word.',say:'Ich habe nur Bahnhof verstanden.'},
{gid:'idiomatik',lv:7,sk:'Idioms',s:'„Übung macht den ___ .“',a:'Meister',o:['Lehrer','Profi','Anfang'],
 ex:'The proverb is „Übung macht den Meister“ — practice makes perfect.',tr:'„Practice makes perfect.“',say:'Übung macht den Meister.'},

/* ---- nuancen ---- */
{gid:'nuancen',lv:7,sk:'Style',s:'Der Streit war nur ___ beigelegt — zwei Wochen später begann er erneut.',a:'scheinbar',o:['anscheinend','sicherlich','womöglich'],
 ex:'The second half proves the appearance was false → scheinbar.',tr:'The dispute was only seemingly settled — two weeks later it started again.',say:'Der Streit war nur scheinbar beigelegt.'},
{gid:'nuancen',lv:7,sk:'Style',s:'___ hat niemand davon gewusst. (wahrscheinlich wahr)',a:'Anscheinend',o:['Scheinbar','Sicher','Eigentlich'],
 ex:'anscheinend means the appearance is probably true: apparently nobody knew.',tr:'Apparently nobody knew about it.',say:'Anscheinend hat niemand davon gewusst.'},
{gid:'nuancen',lv:7,sk:'Style',s:'Es ist ___ acht — wir haben noch Zeit.',a:'erst',o:['nur','schon','bereits'],
 ex:'erst = „not until, only so far“ on a time scale; nur would merely count quantity.',tr:'It is only eight — we still have time.',say:'Es ist erst acht — wir haben noch Zeit.'},
{gid:'nuancen',lv:7,sk:'Style',s:'Ich habe ___ zehn Euro dabei.',a:'nur',o:['erst','schon','bereits'],
 ex:'A plain quantity takes nur; erst would suggest more is still coming.',tr:'I only have ten euros with me.',say:'Ich habe nur zehn Euro dabei.'},
{gid:'nuancen',lv:7,sk:'Style',s:'Das trifft zu, ___ nur unter Vorbehalt.',a:'allerdings',o:['trotzdem','deshalb','sodass'],
 ex:'allerdings concedes a limitation: true, but only with reservations.',tr:'That is true, albeit only with reservations.',say:'Das trifft zu, allerdings nur unter Vorbehalt.'},
{gid:'nuancen',lv:7,sk:'Style',s:'___ bleibt die entscheidende Frage unbeantwortet. (formell, literarisch)',a:'Dennoch',o:['Trotz','Deshalb','Sodass'],
 ex:'dennoch is the formal, literary variant of trotzdem.',tr:'Nevertheless the decisive question remains unanswered.',say:'Dennoch bleibt die entscheidende Frage unbeantwortet.'},
{gid:'nuancen',lv:7,sk:'Style',s:'___ wollte ich bleiben, aber dann wurde es zu spät.',a:'Eigentlich',o:['Scheinbar','Sicherlich','Womöglich'],
 ex:'eigentlich = „actually, with a reservation“ — the plan did not happen.',tr:'Actually I wanted to stay, but then it got too late.',say:'Eigentlich wollte ich bleiben, aber dann wurde es zu spät.'},
{gid:'nuancen',lv:7,sk:'Style',s:'Er wartet ___ auf eine Antwort. (schon lange und jetzt noch)',a:'immer noch',o:['noch immer nicht','erst','bereits'],
 ex:'immer noch stresses that the waiting persists.',tr:'He is still waiting for an answer.',say:'Er wartet immer noch auf eine Antwort.'},

/* ---- textaufbau ---- */
{gid:'textaufbau',lv:7,sk:'Style',s:'Die stärkste Einleitung ist: ___',a:'Die Frage, ob Homeoffice die Produktivität senkt, wird meist falsch gestellt.',o:['Heutzutage ist Homeoffice ein sehr aktuelles Thema.','Es gibt viele Vorteile und Nachteile von Homeoffice.','Ich möchte über Homeoffice schreiben.'],
 ex:'It reframes the question and announces a thesis; the others could precede any text.',tr:'The strongest opening reframes the question.',say:'Die Frage, ob Homeoffice die Produktivität senkt, wird meist falsch gestellt.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Zum Differenzieren: „___ ist zu unterscheiden zwischen Kosten und Nutzen.“',a:'Zunächst',o:['Abschließend','Trotzdem','Heutzutage'],
 ex:'The distinction belongs near the start → Zunächst ist zu unterscheiden zwischen …',tr:'„First a distinction must be made between costs and benefits.“',say:'Zunächst ist zu unterscheiden zwischen Kosten und Nutzen.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Zum Einräumen: „Man wird ___ müssen, dass die Kritik berechtigt ist.“',a:'einräumen',o:['behaupten','ablehnen','beweisen'],
 ex:'„Man wird einräumen müssen, dass …“ is the standard concession formula.',tr:'„One will have to concede that the criticism is justified.“',say:'Man wird einräumen müssen, dass die Kritik berechtigt ist.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Zum Entgegnen: „Dem Argument ist ___ , dass die Daten fehlen.“',a:'entgegenzuhalten',o:['zuzustimmen','festzuhalten','einzuräumen'],
 ex:'„Dem Argument ist entgegenzuhalten, dass …“ answers an objection.',tr:'„Against that argument it must be objected that the data is missing.“',say:'Dem Argument ist entgegenzuhalten, dass die Daten fehlen.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Zum Verstärken: „Dies gilt umso mehr, ___ die Frist knapp ist.“',a:'als',o:['wie','dass','weil'],
 ex:'The fixed formula is „umso mehr, als …“.',tr:'„This is all the more true as the deadline is tight.“',say:'Dies gilt umso mehr, als die Frist knapp ist.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Zum Schluss: „Bleibt also ___ : Der Plan überzeugt nicht.“',a:'festzuhalten',o:['einzuräumen','entgegenzuhalten','zu unterscheiden'],
 ex:'„Bleibt also festzuhalten: …“ draws the consequence at the end.',tr:'„So it must be stated: the plan is not convincing.“',say:'Bleibt also festzuhalten: Der Plan überzeugt nicht.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Ein guter Schluss nennt eine Konsequenz: ___',a:'Daraus folgt, dass eine klare Regelung nötig ist.',o:['Zusammenfassend gibt es Vorteile und Nachteile.','Heutzutage ist das Thema sehr aktuell.','Ich habe über Vorteile und Nachteile geschrieben.'],
 ex:'A conclusion states what follows, not that both sides exist — examiners have read that sentence ten thousand times.',tr:'A good conclusion states a consequence.',say:'Daraus folgt, dass eine klare Regelung nötig ist.'},
{gid:'textaufbau',lv:7,sk:'Style',s:'Das klarste C2-Signal ist: ___',a:'das Gegenargument stark machen und dann beantworten',o:['die eigene Meinung dreimal wiederholen','möglichst viele Idiome einbauen','mit „Heutzutage“ beginnen'],
 ex:'Taking the opposition seriously — even sharpening it — is what makes a reader trust you.',tr:'The clearest C2 signal is to strengthen the counter-argument and then answer it.',say:'Das klarste C2-Signal ist, das Gegenargument stark zu machen und dann zu beantworten.'}

];
